(function(){'use strict';

const D=EIProgression.apply(EIData),P=EIProgression,SAVE='ember-iron-save-v3',BACKUP=SAVE+'-backup',LEASE=SAVE+'-owner',BASE=location.pathname.startsWith('/ember-and-iron')?'/ember-and-iron':'';

const $=q=>document.querySelector(q),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>Math.floor(n||0).toLocaleString(),seconds=n=>n>=120?Math.ceil(n/60)+'m':Math.ceil(Math.max(0,n))+'s',title=s=>s[0].toUpperCase()+s.slice(1);

const initialRoom=new URLSearchParams(location.search).get('room');

const UI={selectedHero:null,followHero:null,room:['smith','mine','forge','shop','adventurers','legacy'].includes(initialRoom)?initialRoom:'smith',modal:null,type:'swords',group:'weapons',heroes:[{name:'Mara',archetypeId:'vanguard'},{name:'Renn',archetypeId:'duelist'},{name:'Wren',archetypeId:'ranger'}],tier:'all',creation:{strength:7,precision:7,charisma:7,knowledge:7},profession:'weaponsmith',name:'Ember & Iron',readonly:false,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches};

const owner=crypto.randomUUID?.()||String(Math.random());let game,storageError='',lastTime=Date.now(),lastSave=0,toastTimer,modalFocus=null,modalStamp='',profile=null,profileSaveBusy=false,pendingProfileSave=null;

function get(k){try{return localStorage.getItem(k);}catch(e){storageError='Automatic saving is unavailable. Export a save to keep your progress.';return null;}}

function put(k,v){try{localStorage.setItem(k,v);return true;}catch(e){storageError='Automatic saving failed. Export your save.';return false;}}

function lease(){let current;try{current=JSON.parse(get(LEASE)||'null');}catch(e){}UI.readonly=!!(current&&current.owner!==owner&&Date.now()-current.time<8000);if(!UI.readonly)put(LEASE,JSON.stringify({owner,time:Date.now()}));}

function save(force=false){if(UI.readonly||!game||(!game.state.started&&game.state.player.legacy.generation===1)||(!force&&Date.now()-lastSave<3000))return;game.markSaved(Date.now());const raw=game.exportSave(),old=get(SAVE);if(old&&old!==raw&&EIWorldEngine.validateSave(old,D).ok)put(BACKUP,old);put(SAVE,raw);lastSave=Date.now();if(profile)syncProfileSave(raw);}

async function api(path,options={}){const response=await fetch(BASE+'/api/'+path,{credentials:'same-origin',headers:{'Content-Type':'application/json','X-Requested-With':'ember-and-iron',...(options.headers||{})},...options});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||'The profile service is unavailable.');return data;}
function syncProfileSave(raw){pendingProfileSave=raw;if(profileSaveBusy)return;profileSaveBusy=true;(async()=>{while(pendingProfileSave){const next=pendingProfileSave;pendingProfileSave=null;try{await api('save',{method:'PUT',body:JSON.stringify({save:next})});}catch(error){storageError='Profile sync is delayed. Your save remains on this device.';}}profileSaveBusy=false;})().catch(()=>{profileSaveBusy=false;});}
async function restoreProfile(){try{const status=await api('profile');if(!status.profile)return;const remote=await api('save');const check=EIWorldEngine.validateSave(remote.save,D);if(!check.ok)throw Error('Your cloud save could not be validated.');profile=status.profile;game=new EIWorldEngine(D,check.state);game.advanceOffline(Date.now());lastTime=Date.now();save(true);render();if(UI.modal==='settings')renderModal();}catch(error){/* The game remains fully playable as a guest when the profile service is unavailable. */}}
async function profileAction(kind){const username=$('#profile-name')?.value.trim(),password=$('#profile-password')?.value;if(!username||!password){toast('Enter a profile name and password.');return;}try{const result=await api(kind,{method:'POST',body:JSON.stringify(kind==='signup'?{username,password,save:game.exportSave()}:{username,password})});profile=result.profile;if(result.save){const check=EIWorldEngine.validateSave(result.save,D);if(!check.ok)throw Error('That profile has an incompatible save.');game=new EIWorldEngine(D,check.state);game.advanceOffline(Date.now());lastTime=Date.now();save(true);}close();render();toast(kind==='signup'?'Profile created — this workshop is now backed up.':'Welcome back, '+profile.username+'.');}catch(error){toast(error.message);}}
async function logoutProfile(){try{await api('logout',{method:'POST',body:'{}'});}catch(error){}profile=null;pendingProfileSave=null;renderModal();render();toast('You are now playing as a guest on this device.');}

let saved=null;for(const key of [SAVE,BACKUP]){const raw=get(key);if(raw){const result=EIWorldEngine.validateSave(raw,D);if(result.ok){saved=result.state;break;}storageError='A damaged save was detected. Import an export to restore it.';}}

game=new EIWorldEngine(D,saved);lease();if(!UI.readonly&&saved)game.advanceOffline(Date.now());restoreProfile();

function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}

function btn(label,action,data={},disabled=false,cls=''){return `<button class="${cls}" data-action="${action}" ${Object.entries(data).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')} ${disabled?'disabled':''}>${label}</button>`;}

const glyphs={smith:'✦',mine:'◆',forge:'♨',shop:'◇',adventurers:'⚑',legacy:'✧'};

function icon(id){const shape={swords:'M10 38L35 7 40 5 39 11 15 41M8 31L22 43M6 43L11 38',daggers:'M12 36L31 14 38 10 35 18 17 40M9 30L24 43',axes:'M13 44L33 10M25 12Q42 5 43 24L29 25M25 12L17 7 12 19 25 23',maces:'M12 44L32 19M25 6L40 8 43 22 30 27 21 16Z',polearms:'M9 46L38 9M38 9L31 17 42 20 38 9',bows:'M15 5Q46 25 15 45L23 25Z M7 25L39 25M33 20L39 25 33 30',armor:'M15 7L6 12 10 24 15 20 13 43 37 43 35 20 40 24 44 12 35 7Q25 17 15 7Z',shields:'M25 6L42 13 39 32Q32 41 25 46 11 38 9 24L8 13Z M25 11L25 39',rings:'M37 29A12 12 0 1 1 13 29 12 12 0 1 1 37 29 M17 12L24 5 33 12 25 21Z',foci:'M13 44L29 17M24 6L36 6 40 17 29 24 20 15Z',charms:'M14 7Q25 35 37 7M25 27L15 37 25 46 35 37Z',tools:'M10 44L34 14M15 15Q30 4 45 18M26 13L25 25',cloth_armor:'M16 8L6 15 12 24 17 19 12 44 38 44 33 19 38 24 44 15 34 8 25 14Z M25 14L25 40 M19 29L31 29',leather_armor:'M17 7L10 15 15 21 13 43 37 43 35 21 40 15 33 7 25 12Z M20 18L30 24M30 18L20 24M20 25L30 31M30 25L20 31M15 34L35 34',offhands:'M25 12Q15 5 6 10L6 41Q16 36 25 43Q34 36 44 41L44 10Q35 5 25 12L25 43 M11 18L20 20 M30 20L39 18 M11 25L20 27 M30 27L39 25',instruments:'M8 12L17 12Q18 31 39 22L44 38Q16 49 12 19L8 19Z M36 23L41 40 M22 35L25 28',talismans:'M12 7Q25 32 38 7 M25 23L14 33 20 44 30 44 36 33Z M25 29L21 36 29 36 25 41'}[id]||'M25 7L42 25 25 43 8 25Z';return `<svg viewBox="0 0 50 50" class="item-icon" aria-hidden="true"><path d="${shape}" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}

function bar(value,max,cls=''){return `<div class="bar ${cls}"><i style="width:${Math.max(0,Math.min(100,100*value/Math.max(1,max)))}%"></i></div>`;}

const artUrls={};
function art(room){const key=EIRoomModel.artKey(game,room);if(artUrls[key])return artUrls[key];const source=window.EIArt?.[key];if(!source)return 'assets/'+key+'.png';if(!source.startsWith('data:'))return source;const split=source.indexOf(','),binary=atob(source.slice(split+1)),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return artUrls[key]=URL.createObjectURL(new Blob([bytes],{type:'image/png'}));}


function objective(){const s=game.state,d=game.derived();if(s.player.points)return{title:'Shape your next strength',text:`${s.player.points} attribute points are waiting.`,room:'smith',cta:'Develop your smith'};if(s.inventory.length+s.jobs.length>=d.storageCapacity)return{title:'Make room for your next piece',text:'Your warehouse is full. Display, sell or salvage a piece, or expand storage.',room:'shop',cta:'Manage the warehouse'};if(s.inventory.some(i=>!i.displayed&&!i.autoDisplayHold&&!game._protected(i))&&s.inventory.filter(i=>i.displayed).length<d.displayCapacity)return{title:'Bring your work into the light',text:'Useful stock is waiting in the warehouse. Move a piece onto an open display.',room:'shop',cta:'Fill your displays'};if(!s.jobs.length){const recipe=visibleRecipes().find(r=>r.classId===UI.type)||visibleRecipes()[0];if(recipe){const short=Object.entries(recipe.inputs).filter(([id,n])=>s.materials[id]<n);if(short.length){const buy=short.some(([id])=>!game.seams().some(v=>v.id===id));return{title:buy?'Restock your crafting supplies':'Return to the mountain',text:recipe.name+' needs '+short.map(([id,n])=>(n-s.materials[id])+' '+D.materials[id].name).join(', ')+(buy?'. Buy supplies directly in Mine or Forge.':'. Click a seam or assign a worker.'),room:'mine',cta:buy?'Buy missing supplies':'Gather the missing materials'};}}}if(!s.stats.crafted){if(s.jobs.length)return{title:'Your first piece is taking shape',text:'Optional Quality finish adds +20 quality up to the forge cap and +10 percentage points prefix chance, but doubles work time. Completed items fill open displays.',room:'forge',cta:'Watch the forge'};return{title:'A first blade. A first beginning.',text:'Choose a training weapon your starting company can use. The materials are ready.',room:'forge',cta:'Make your first weapon'};}if(!s.inventory.some(i=>i.displayed)&&!s.jobs.length)return{title:'Give them a reason to return',text:'Forge fresh stock. Adventurers only buy useful, affordable improvements.',room:'forge',cta:'Craft for your customers'};if(!s.stats.questsWon)return{title:'Help them survive the road',text:'A weapon is only the beginning. Try armour and shields while your first class improves.',room:'forge',cta:'Broaden your shelves'};const nextBoss=D.tierBosses.map(id=>D.quests[id]).find(q=>!s.questWins[q.id]);if(nextBoss&&game._gates(nextBoss.requires).every(g=>g.met)&&!s.runs.some(r=>r.questId===nextBoss.id&&!['complete','pending'].includes(r.status)))return{title:s.world.bossTarget?'Your boss party is gathering':'A tier boss stands in your path',text:s.world.bossAutoLaunch?'Your selected heroes will depart automatically after returning and recovering.':nextBoss.name+' is ready to challenge. Select a party, review its forecast, then Gather and launch.',room:'adventurers',cta:'Review the boss party'};if(!s.world.trees.mine_depths_0)return{title:'Beyond bronze',text:'Reach smith level 2 and earn 2 Prospecting to expose the iron seam.',room:'mine',cta:'Explore the mine'};return{title:'Build a name that outlives you',text:`${d.legacyBreakdown.bossesDefeated} / 5 tier bosses defeated. ${d.legacyEligible?'The final boss has unlocked Legacy retirement.':'Improve equipment and clear each tier. Legacy unlocks after the Void Sovereign.'}`,room:d.legacyEligible?'legacy':'adventurers',cta:d.legacyEligible?'Enter Legacy':'Prepare the next boss'};}

function header(){const s=game.state;return `<header class="topbar"><button class="brand" data-action="room" data-room="smith"><span class="brandmark">E<span>Ⅰ</span></span><span>EMBER <em>&</em> IRON<small>${esc(s.shopName)}</small></span></button><nav aria-label="Workshop rooms">${Object.keys(glyphs).map((r,i)=>btn(`<span>${glyphs[r]}</span>${title(r)}<small>0${i+1}</small>${r==='legacy'&&!EIRoomModel.legacyUnlocked(game)?'<span class="lock-note">Defeat the tier 5 boss to unlock Legacy</span>':''}`,'room',{room:r},r==='legacy'&&!EIRoomModel.legacyUnlocked(game),(UI.room===r?'active ':'')+(r==='legacy'&&!EIRoomModel.legacyUnlocked(game)?'legacy-locked':''))).join('')}</nav><div class="wealth"><span class="coin">◉</span><strong>${num(s.player.gold)}</strong><small>GOLD</small></div>${btn('☰','modal',{modal:'settings'},false,'settings-button')}</header>`;}

function companyFields(){return `<section class="creation-company"><h3>Your starting company</h3><p>Choose three names and classes. Front-line heroes protect Rangers and Mages in the back line.</p>${UI.heroes.map((h,i)=>`<div class="company-choice"><label>Hero ${i+1}<input data-company-name="${i}" maxlength="28" value="${esc(h.name)}"></label><label>Class<select data-company-class="${i}">${Object.values(D.archetypes).map(a=>`<option value="${a.id}" ${a.id===h.archetypeId?'selected':''}>${a.name} · ${a.line} line</option>`).join('')}</select></label><small>${(P.access[h.archetypeId]||[]).map(id=>D.classes[id].name).join(' · ')}</small></div>`).join('')}</section>`;}
function staffPanel(){const s=game.state;return `<p class="panel-note">On duty: −2 stamina/min. Time off: +${(10*(1+(game._effects().staffRecovery||0))).toFixed(0)}/min. Effectiveness is 100% at 70+ stamina, 75% at 35+, 40% until exhausted. Resume shifts yourself.</p><div class="staff-grid">${Object.values(D.staff).map(def=>{const st=s.staff[def.id],cost=game.staffPrice(def.id),missing=game._gates(def.requires).filter(g=>!g.met);return `<article class="employee-card"><div class="row"><h3>${def.name}</h3><span class="badge">${st?'Level '+st.level:'Specialist'}</span></div><p>${def.description}</p>${st?`<div class="row"><small>Experience</small><strong>${st.level>=5?'Master employee':Math.floor(st.xp)+' / '+30*st.level}</strong></div>${bar(st.level>=5?1:st.xp,st.level>=5?1:30*st.level)}<div class="row"><small>Stamina</small><strong>${Math.round(st.stamina)} / 100</strong></div>${bar(st.stamina,100,'stamina')}<div class="row"><small>${st.active?(st.stamina<=0?'Exhausted · needs time off':Math.round(game.staffEfficiency(def.id)*100)+'% effectiveness'):'Time off · recovering'}</small>${btn(st.active?'Give time off':'Resume duty','staff-toggle',{id:def.id})}</div>`:btn('Hire · '+cost+'g','staff-hire',{id:def.id},s.player.gold<cost||missing.length>0)+(missing.length?'<small class="panel-note">Requires '+missing.map(g=>g.label+' '+g.required).join(' · ')+'</small>':'')}</article>`;}).join('')}</div>`;}
function furnishingEffects(def,level){const labels={arrival:'customer cadence',budget:'customer budgets',speed:'craft speed',staffRecovery:'staff recovery',quality:'quality',proficiencyXp:'proficiency XP',relationship:'relationship per sale',enchant:'enchantment strength'};return Object.entries(def.effects).map(([key,value])=>'+'+(['quality','relationship'].includes(key)?value*level:Math.round(value*level*100)+'%')+' '+labels[key]).join(' · ');}
function furnishingsPanel(){return `<p class="panel-note">Five permanent levels per furnishing. Each level adds its listed bonuses; the next purchase costs 2.4× more. All levels survive Legacy.</p><div class="furnishing-grid">${Object.values(D.decor).map(d=>{const v=game.decorationPreview(d.id);return `<article class="furnishing"><div class="row"><h3>${d.name}</h3><span class="badge">Level ${v.level} / ${v.maxLevel}</span></div><div class="furnishing-levels" aria-label="${esc(d.name)} level ${v.level} of ${v.maxLevel}">${Array.from({length:v.maxLevel},(_,i)=>`<i class="${i<v.level?'filled':''}"></i>`).join('')}</div><p>${v.level?furnishingEffects(d,v.level):'Not installed'}</p>${v.level<v.maxLevel?`<small>Next level adds ${furnishingEffects(d,1)}</small>`:'<small>Maximum permanent bonus</small>'}${btn(v.level>=v.maxLevel?'Fully upgraded':(v.level?'Upgrade to level '+(v.level+1):'Install level 1')+' · '+num(v.cost)+'g','decorate',{id:d.id},!v.eligible)}</article>`;}).join('')}</div>`;}

function supplyButtons(){return `<div class="purchased-supplies" aria-label="Purchased crafting supplies">${D.purchasedSupplies.map(id=>{const amount=game.state.materials[id]||0,room=game.binCapacity()-amount,price=game.materialPrice(id);return `<div class="supply-entry"><span class="supply-name" title="${esc(D.materials[id].description)}"><i class="material-dot" style="background:${D.materials[id].color}"></i>${D.materials[id].name}</span><strong class="supply-amount" aria-label="${D.materials[id].name} in stock">${num(amount)}</strong><div class="supply-actions">${[1,5].map(wanted=>{const qty=Math.min(wanted,Math.max(1,room));return btn('Buy '+qty+' · '+num(price*qty)+'g','buy',{material:id,quantity:qty},room<1||game.state.player.gold<price*qty);}).join('')}</div></div>`;}).join('')}</div>`;}
function materialTrade(id){const s=game.state,n=Math.min(5,s.materials[id]),cost=game.materialPrice(id);return `<div class="seam-trade">${[1,5].map(q=>btn('Buy '+q+' · '+cost*q+'g','buy',{material:id,quantity:q},s.player.gold<cost*q||s.materials[id]+q>game.binCapacity())).join('')}${btn('Sell '+n+' · '+(game.materialSalePrice(id,n)||0)+'g','sell-material',{material:id,quantity:n},n<1)}</div>`;}
function requestList(){return game.craftableRequests(5);}

function recruitmentPanel(){const empty=game.state.world.unlockedHeroIds.filter(id=>!game.state.world.heroChoices[id]);return panel('Hire your company',empty.length?`<div class="recruitment-slots">${empty.map((id,i)=>`<article><h3>Open charter ${i+1}</h3><p>Choose a name and class. Equipment access follows the hero you hire.</p>${btn('Name & recruit','recruit',{id},false,'primary')}</article>`).join('')}</div>`:'<p class="panel-note">All open charters are filled. Develop Recruitment to open the next slot.</p>',btn('Recruitment upgrades','modal',{modal:'upgrades'}));}
function questBoard(){
 const s=game.state,rows=Object.values(D.quests),available=rows.filter(q=>s.unlocks.quests.includes(q.id)),next=rows.find(q=>!s.unlocks.quests.includes(q.id));
 return `<div class="company-quest-progress"><h4>Company quest progress</h4><p class="panel-note">Every tier: Level 1 → Level 2 → Level 3 → Boss. Win 5 at each level; defeat the boss to enter the next tier. Each winning party member adds one count.</p><div class="quest-progress-list">${[...available,...(next?[next]:[])].map(q=>{const won=s.questWins[q.id]||0,target=q.masteryTarget,unlocked=s.unlocks.quests.includes(q.id);return `<article title="${esc(q.description)}"><div class="row"><strong>${q.name}</strong><small>Tier ${q.tier} · ${q.manualBoss?'Boss':'Level '+q.questLevel} · ${q.rounds} rounds</small></div><div class="quest-count"><span>${q.manualBoss?'Boss victories':'Hero victories'}</span><b>${Math.min(won,target)} / ${target}</b></div><div class="bar" role="progressbar" aria-label="${q.name} victories" aria-valuemin="0" aria-valuemax="${target}" aria-valuenow="${Math.min(won,target)}"><i style="width:${Math.min(100,100*won/target)}%"></i></div><small>${unlocked?(won>=target?(q.manualBoss?(q.tier<5?'Tier '+(q.tier+1)+' unlocked':'Legacy unlocked'):(q.questLevel<3?'Level '+(q.questLevel+1)+' unlocked':'Boss approach cleared')):q.manualBoss?'Launch a selected boss party':'Enemies: +'+Math.round(35*Math.min(won,target)/target)+'% health · +'+Math.round(20*Math.min(won,target)/target)+'% attack'):'Locked: '+game._gates(q.requires).filter(g=>!g.met).map(g=>g.label+' '+g.current+'/'+g.required).join(' · ')}</small></article>`;}).join('')}</div></div>`;
}

function creation(){const remaining=28-Object.values(UI.creation).reduce((a,b)=>a+b,0);return `<div class="creation" style="--room-art:url('${art('smith')}')"><div class="creation-intro"><div class="eyebrow">EMBER & IRON · THE FOUNDRY</div><h1>Every legend<br>begins with<br><em>a maker.</em></h1><p>The heroes will carry your work into the dark.<br>Build the workshop that brings them home.</p><div class="intro-steps"><span>01 Mine</span><i>→</i><span>02 Forge</span><i>→</i><span>03 Provide</span></div></div><main class="creation-card"><div class="eyebrow">YOUR FIRST CHAPTER</div><h2>Become the smith</h2><label class="field">Workshop name<input id="shop-name" maxlength="48" value="${esc(UI.name)}"></label><label class="field">Your profession<select id="profession">${Object.entries(P.professions).map(([id,p])=>`<option value="${id}" ${id===UI.profession?'selected':''}>${p.name}</option>`).join('')}</select></label><div class="profession-note"><strong>${P.professions[UI.profession].title}</strong><p>${P.professions[UI.profession].description}</p></div><div class="row"><h3>Choose your strengths</h3><span class="badge">${remaining} points left</span></div>${attributes(true)}<p class="muted small">20 starting points. No attribute caps. Earn 5 more points at every smith level.</p>${game.state.player.legacy.generation>1?btn('Spend Legacy sparks: '+game.state.player.legacy.points,'room',{room:'legacy'},false,'legacy-creation'):''}${companyFields()}${btn('Light the forge <span>→</span>','create',{},remaining!==0,'primary begin')}${btn('Import an existing legacy','import',{},false,'text-button')}</main><div class="creation-footer">A quiet beginning. An extraordinary legacy.</div></div>`;}

const statText={strength:'Faster crafting · heavier quality · manual yield · carrying capacity',precision:'Higher quality · more special affixes',charisma:'Higher prices · larger customer budgets · longer browsing',knowledge:'Higher quality · faster proficiency · stronger enchantments'};

function attributes(create=false){const a=create?UI.creation:game.state.player.stats,p=game.state.player;return `<div class="attributes">${Object.entries(a).map(([id,v])=>`<div class="attribute"><span class="stat-symbol">${{strength:'⚒',precision:'◎',charisma:'♜',knowledge:'✧'}[id]}</span><div><strong>${title(id)}</strong><small>${statText[id]}</small></div><div class="stepper">${create?btn('−','creation-stat',{stat:id,delta:-1},v<=2):''}<b>${v}</b>${btn('+',create?'creation-stat':'allocate',{stat:id,delta:1},create?Object.values(a).reduce((x,y)=>x+y,0)>=28:p.points<1)}</div></div>`).join('')}</div>`;}

function scene(){return `<main class="world dashboard-world room-${UI.room}" data-room="${UI.room}" data-art="${EIRoomModel.artKey(game,UI.room)}" style="--room-art:url('${art(UI.room)}')">${roomToolbar()}${objectiveStrip()}<div class="follow-holder">${followStrip()}</div><div class="room-body">${roomContent()}</div><div class="world-footer"><span>Progress saved automatically</span><span>GENERATION ${game.state.player.legacy.generation}</span></div></main>`;}

function seamRequirement(seam){const n=Object.values(P.nodes).find(n=>n.effects[seam.effect]);return (n?.level?'Level '+n.level+' · ':'')+(n?.requiresEffect?'Smelter · ':'')+(n?.cost||0)+' Prospecting';}





function visibleRecipes(){const materialNames=Object.values(D.materials).map(m=>m.name);return Object.values(D.recipes).filter(r=>game._recipeKnown(r)&&game.craftPreview(r.id).gates.filter(g=>!materialNames.includes(g.label)).every(g=>g.met));}

function forgeDock(){const available=game.availableClasses(),groups=['weapons','armour','other'].filter(g=>available.some(id=>D.classes[id].group===g));if(!groups.includes(UI.group))UI.group=groups[0];const types=available.filter(id=>D.classes[id].group===UI.group);if(!types.includes(UI.type))UI.type=types[0];const recipes=visibleRecipes().filter(r=>r.classId===UI.type),tiers=[...new Set(recipes.map(r=>r.tier))];if(UI.tier!=='all'&&!tiers.includes(Number(UI.tier)))UI.tier='all';return `<div class="group-filters">${groups.map(g=>btn(title(g),'group-filter',{group:g},false,UI.group===g?'selected':'')).join('')}</div><div class="recipe-filters"><div class="type-filters">${types.map(id=>btn(D.classes[id].name,'filter',{type:id},false,UI.type===id?'selected':'')).join('')}</div><label>Tier <select id="tier-filter"><option value="all">All unlocked tiers</option>${tiers.map(n=>`<option value="${n}" ${UI.tier===String(n)?'selected':''}>${n}</option>`).join('')}</select></label></div>${nextRecipePanel()}<div class="recipe-strip">${recipes.filter(r=>UI.tier==='all'||r.tier===Number(UI.tier)).sort((a,b)=>a.tier-b.tier||a.variant-b.variant).map(recipeCard).join('')||'<p class="empty">Develop the next pattern requirements to craft this class.</p>'}</div>`;}

function recipeCard(r){const p=game.craftPreview(r.id),prof=game.state.player.proficiency[r.classId];return `<article class="recipe-card tier-${r.tier}"><div class="recipe-top">${icon(r.classId)}<div><strong>${esc(r.name)}</strong><small>Tier ${r.tier} · ${D.classes[r.classId].name} · proficiency ${prof.level}</small></div></div><p class="pattern-note">${esc(r.description)}</p><div class="craft-details"><span>Q${p.quality} <small>quality</small></span><span>${seconds(p.seconds)} <small>work</small></span><span>~${p.price}g <small>sale</small></span></div><div class="ingredient-line">${Object.entries(r.inputs).map(([id,n])=>`<span class="${game.state.materials[id]<n?'missing':''}">${n} ${D.materials[id].name}</span>`).join(' · ')}</div><div class="craft-buttons">${btn('Craft 1','craft',{recipe:r.id,quantity:1},!p.eligible,'primary')}${btn('5','craft',{recipe:r.id,quantity:5},!game.craftPreview(r.id,{quantity:5}).eligible)}${btn('Max '+p.maxQuantity,'craft',{recipe:r.id,quantity:p.maxQuantity},!p.eligible||p.maxQuantity<1)}</div>${!p.eligible?`<small class="craft-reason">${esc(p.reason)}</small>`:''}</article>`;}

function quality(q){return EICampaign.qualityName(q);}
function itemName(i){return EICampaign.itemName(i,D);}

function itemCard(i,manage=false){const r=D.recipes[i.recipeId];return `<article class="stock-card ${quality(i.quality)}"><button class="stock-open" data-action="item" data-id="${i.id}">${icon(r.classId)}<span><strong>${esc(itemName(i))}</strong><small><i class="material-dot tier-${r.tier}"></i>${D.materials[r.materialId||Object.keys(r.inputs)[0]]?.name||'Metal'} · Q${i.quality} ${quality(i.quality)}</small><small>${[i.affixId?'✦ '+D.affixes[i.affixId].name:'No prefix',i.enchantmentId?'✧ '+D.enchantments[i.enchantmentId].suffix:'No suffix'].join(' · ')} · ${game.itemPrice(i.id)}g</small></span></button><div class="stock-bottom"><span>${i.protected?'Protected':i.reservedFor?'Reserved':i.autoDisplayHold?'Held in warehouse':i.displayed?'On display':'In warehouse'}</span>${manage?`<div class="shelf-actions">${btn(i.autoDisplayHold?'Release':i.displayed?'Hold':'Display','display',{id:i.id})}${btn('Sell '+game.salePreview(i.id).price+'g','town-sell',{id:i.id},!game.salePreview(i.id).eligible)}${btn('Scrap','salvage',{id:i.id},game._protected(i))}</div>`:''}</div></article>`;}


function heroCard(h){const run=game.state.runs.find(r=>r.id===h.runId&&!r.rewardApplied),v=run?game.battleView(run.id):null;const hp=v?.heroes.find(x=>x.id===h.id);const status={browsing:'Browsing the shelves',ready:'Checking equipment',recovering:'Resting after a retreat',idle:'At the guild',travelling:'Travelling to the quest',fighting:'In battle',returning:'Returning home'}[h.status]||h.status;return `<article class="hero-card"><div class="hero-heading"><span class="hero-seal ${h.archetypeId}">${icon((P.access[h.archetypeId]||[])[0])}</span><div><strong>${esc(h.name)}</strong><small>${D.archetypes[h.archetypeId].name} · level ${h.level}</small></div><b class="status-light ${h.status}"></b></div><div class="quest-vignette ${h.status}"><span class="mini-hero">⚔</span><span class="quest-trail"></span><span class="mini-enemy">${run?'◆':'⌂'}</span></div><div class="row small"><strong>${status}</strong><span>${run?seconds(v.returnIn/1000):h.status==='recovering'?seconds((h.recoverUntil-game.state.simTime)/1000):''}</span></div>${hp?bar(hp.hp,hp.maxHp,'health'):bar(h.status==='recovering'?Math.max(0,h.recoverUntil-game.state.simTime):1,h.status==='recovering'?180000:1)}<small>${run?D.quests[run.questId].name:h.shoppingReason||'Preparing for the next expedition'}</small>${btn(run?'Watch quest →':'View adventurer →',run?'watch':'hero',{id:run?run.id:h.id},false,'text-button')}</article>`;}



// Reconcile live values without replacing focused controls or click targets.

function syncNode(old,next){if(old.nodeType!==next.nodeType||old.nodeName!==next.nodeName){old.replaceWith(next.cloneNode(true));return;}if(old.nodeType===3){if(old.nodeValue!==next.nodeValue)old.nodeValue=next.nodeValue;return;}if(old.nodeType!==1)return;if(old===document.activeElement&&['INPUT','SELECT','TEXTAREA'].includes(old.tagName))return;const keepDetails=old.tagName==='DETAILS'&&old.dataset.detailKey&&old.dataset.detailKey===next.dataset.detailKey,wasOpen=old.open;for(const attr of [...old.attributes])if(!next.hasAttribute(attr.name)&&!(old.tagName==='CANVAS'&&['width','height'].includes(attr.name)))old.removeAttribute(attr.name);for(const attr of [...next.attributes])if(old.getAttribute(attr.name)!==attr.value)old.setAttribute(attr.name,attr.value);if(keepDetails)old.open=wasOpen;syncChildren(old,next);}

function syncChildren(old,next){const target=[...next.childNodes];for(let i=0;i<target.length;i++){if(!old.childNodes[i])old.appendChild(target[i].cloneNode(true));else syncNode(old.childNodes[i],target[i]);}while(old.childNodes.length>target.length)old.lastChild.remove();}

function content(el,html){const t=document.createElement('template');t.innerHTML=html;syncChildren(el,t.content);}

function element(el,html){const t=document.createElement('template');t.innerHTML=html;syncNode(el,t.content.firstElementChild);}

function masteryHint(id){const prof=game.state.player.proficiency[id].level,reduction=game._effects().proficiencyGateReduction||0;const next=[15,30,50,75].map(v=>Math.max(0,v-reduction)).find(v=>v>prof);return next?'Next material mastery: '+prof+' / '+next+' (other unlocks still apply)':'All material mastery thresholds met';}
function gearGaps(h){const classes=D.archetypes[h.archetypeId].preferences.filter(id=>game.availableClasses().includes(id));const missing=[...new Set(classes.map(id=>D.classes[id].slot))].filter(slot=>!h.equipment[slot]&&(slot!=='offhand'||!D.recipes[h.equipment.weapon?.recipeId]?.twoHanded));return missing.length?'<div class="gear-gaps"><strong>Needs workshop gear:</strong> '+missing.map(title).join(', ')+'. Stock these slots to improve survival.</div>':'<div class="gear-gaps">All available equipment slots supplied. Improve material and quality for harder quests.</div>';}
const combatNumber=n=>Number(n.toFixed(1)).toLocaleString();
function heroEquipTypes(h){const a=D.archetypes[h.archetypeId],blocked=D.recipes[h.equipment.weapon?.recipeId]?.twoHanded;return `<section class="hero-equip-types"><h3>${a.name} · can equip</h3><div class="equip-type-list">${a.preferences.map(id=>`<span>${icon(id)}<span>${D.classes[id].name} <small>· ${title(D.classes[id].slot)}</small></span></span>`).join('')}</div>${blocked?'<p class="panel-note">The current two-handed weapon blocks the offhand slot.</p>':''}</section>`;}
function heroStatsPanel(h){
 const v=game.heroCombatSummary(h.id),s=v.stats;
 const rows=[['Damage / hit',combatNumber(s.attack),title(s.damageType)+' · '+combatNumber(v.damageMin)+'–'+combatNumber(v.damageMax)+' normal hit before enemy defences'],['Health',v.inExpedition?combatNumber(v.currentHealth)+' / '+combatNumber(v.maxHealth):combatNumber(v.maxHealth),v.inExpedition?'Current / maximum':'Maximum health'],['Expected DPS',combatNumber(v.expectedDps),'Single target · includes crit chance'],['Attack interval',combatNumber(s.interval)+'s','Time between attacks'],['Armour',combatNumber(s.armor),'Reduces incoming damage'],['Penetration',combatNumber(s.armorPen),'Ignores enemy armour'],['Critical chance',combatNumber(s.crit*100)+'%','Critical hits deal 1.5× damage'],['Block',combatNumber(s.block*100)+'%','Blocks halve damage'],['Evasion',combatNumber(s.evasion*100)+'%','Chance to avoid a hit']];
 return `<section class="hero-stat-panel"><div class="row"><h3>Combat stats</h3><span class="badge">${v.inExpedition?'Current expedition':'Current equipment'}</span></div><dl class="hero-stat-list">${rows.map(([label,value,note])=>`<div title="${note}"><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl><p class="resistance-line"><strong>Resistances</strong> ${Object.entries(s.resistances).filter(([,n])=>n>0).map(([id,n])=>title(id)+' '+combatNumber(n*100)+'%').join(' · ')||'None'}${s.guardian?' · Protects allies: '+combatNumber(s.protection*100)+'% less damage':''}${s.aoe?' · Splash damage: '+combatNumber(s.aoe*100)+'%':''}</p><div class="hero-xp"><div class="row"><strong>Level ${h.level}</strong><small>${v.maxLevel?'Maximum level reached':num(v.experience)+' / '+num(v.experienceRequired)+' XP · next level '+(h.level+1)}</small></div><div class="bar hero-experience" role="progressbar" aria-label="${esc(h.name)} experience" aria-valuemin="0" aria-valuemax="${v.maxLevel?1:v.experienceRequired}" aria-valuenow="${v.maxLevel?1:Math.min(v.experience,v.experienceRequired)}"><i style="width:${v.maxLevel?100:Math.min(100,100*v.experience/v.experienceRequired)}%"></i></div></div><p class="panel-note">Includes gear, level, class and training${v.inExpedition?', plus this party’s bonus':''}. Damage is before enemy defences.</p></section>`;
}

function equipmentContributions(stats,weapon=false){
 const rows=[['attack','Damage',1,''],['health','Health',1,''],['armor','Armour',1,''],['armorPen','Penetration',1,''],['crit','Critical chance',100,'%'],['block','Block',100,'%'],['evasion','Evasion',100,'%']].filter(([id])=>stats[id]).map(([id,label,scale,unit])=>`${label} ${stats[id]>0?'+':''}${combatNumber(stats[id]*scale)}${unit}`);
 if(weapon&&stats.interval)rows.push(combatNumber(stats.interval)+'s attack interval');
 if(weapon&&stats.damageType)rows.push(title(stats.damageType)+' damage');
 for(const [type,n]of Object.entries(stats.resistances||{}))if(n)rows.push(title(type)+' resistance '+combatNumber(n*100)+'%');
 return rows.map(value=>`<span>${esc(value)}</span>`).join('')||'<span>No combat bonus</span>';
}
function equippedItem(h,slot){
 const item=h.equipment[slot],blocked=slot==='offhand'&&D.recipes[h.equipment.weapon?.recipeId]?.twoHanded;
 if(!item){const worn=slot==='weapon'?D.starting?.wornWeapon:slot==='body'?D.starting?.wornBody:null;return `<div class="equipped-piece empty-equipment"><strong>${blocked?'Blocked by two-handed weapon':worn?'Worn starting '+(slot==='body'?'armour':'weapon'):'No item equipped'}</strong><div class="item-contributions">${worn?equipmentContributions(worn,slot==='weapon'):'<span>'+ (blocked?'Use a one-handed weapon to equip this slot.':'Fill this slot for additional combat bonuses.')+'</span>'}</div></div>`;}
 const recipe=D.recipes[item.recipeId],material=D.materials[recipe.materialId||Object.keys(recipe.inputs)[0]],prefix=D.affixes[item.affixId],suffix=D.enchantments[item.enchantmentId];
 return `<div class="equipped-piece quality-${quality(item.quality)}"><div class="equipped-title">${icon(recipe.classId)}<div><strong>${esc(itemName(item))}</strong><small><i class="material-dot" style="background:${material?.color||'#c5a16c'}"></i>${esc(material?.name||'Crafted')} · Tier ${recipe.tier} · Q${item.quality} ${title(quality(item.quality))}${recipe.twoHanded?' · Two-handed':''}</small></div></div><div class="item-contributions" aria-label="Item contribution">${equipmentContributions(game._itemCombat(item),slot==='weapon')}</div><div class="equipped-modifiers"><span>${prefix?'✦ '+esc(prefix.name)+': '+esc(prefix.description):'No crafted prefix'}</span><span>${suffix?'✧ '+esc(suffix.suffix)+': '+esc(suffix.description)+' · '+combatNumber(item.enchantStrength||game.derived().enchantStrength)+'× enchant strength':'No enchanted suffix'}</span></div></div>`;
}
function heroEquipmentPanel(h){
 const slots=['weapon','body','offhand','ring','charm','tool'];
 return `<section class="hero-equipment-guide equipped-only"><h3>Equipped items</h3><div class="equipment-loadout">${slots.map(slot=>`<section class="equipment-slot" data-slot="${slot}"><h4>${title(slot)}</h4><div class="equipment-slot-body">${equippedItem(h,slot)}</div></section>`).join('')}</div></section>`;
}

function legacyBreakdown(){const d=game.derived(),b=d.legacyBreakdown;return `<div class="legacy-breakdown"><strong>${d.legacyEligible?'Retirement spark sources':'Legacy locked: defeat the tier 5 boss'}</strong><p>Final boss ${b.finalBoss} + tier boss difficulty ${b.tierBosses} + smith milestones ${b.smithMilestones} + masterwork variety ${b.masterworkDesigns}</p><small>${b.bossesDefeated} / 5 tier bosses defeated. Repeat boss victories add no sparks. Rewards become available after defeating the Void Sovereign.</small></div>`;}
function panel(name,body,actions='',cls=''){return `<section class="info-panel ${cls}"><div class="panel-heading"><h2>${name}</h2><div>${actions}</div></div>${body}</section>`;}
function statTiles(rows){return `<div class="metric-strip">${rows.map(([name,value,detail])=>`<div><small>${name}</small><strong>${value}</strong>${detail?`<span>${detail}</span>`:''}</div>`).join('')}</div>`;}
function resourceList(){return `<div class="resource-list">${Object.values(D.materials).sort((a,b)=>a.id==='fuel'?-1:b.id==='fuel'?1:0).filter(m=>!m.purchasedSupply&&(game.materialAvailable(m.id)||game.state.materials[m.id])).map(m=>`<div><span><i class="material-dot" style="background:${m.color||'#c58edd'}"></i>${m.name}</span><strong>${num(game.state.materials[m.id])}<small> / ${game.binCapacity()}</small></strong></div>`).join('')}</div>`;}
function eventList(types,limit=5){return `<div class="event-list">${game.state.logs.filter(l=>!types||types.includes(l.type)).slice(0,limit).map(l=>`<div><span class="event-dot ${l.type}"></span><p>${esc(l.text)}</p><small>${seconds((game.state.simTime-l.time)/1000)} ago</small></div>`).join('')||'<p class="empty">Your story is just beginning.</p>'}</div>`;}
function objectiveStrip(){if(UI.room==='legacy')return `<div class="objective-strip legacy-objective"><span class="eyebrow">BEYOND THIS LIFETIME</span><div><strong>${game.state.player.legacy.generation<2?'Your first legacy awaits':'Build a lasting inheritance'}</strong><p>${game.state.player.legacy.generation<2?'Retire to earn sparks and open four permanent talent paths.':'Spend sparks on permanent talents. Defeat the Void Sovereign again to retire this generation.'}</p></div>${btn(game.state.started?'View collection →':'Return to character creation →',game.state.started?'modal':'room',game.state.started?{modal:'collection'}:{room:'smith'},false,'text-button')}</div>`;const o=objective();return `<div class="objective-strip"><span class="eyebrow">NEXT STEP</span><div><strong>${o.title}</strong><p>${o.text}</p></div>${btn(o.cta+' →','room',{room:o.room},false,'text-button')}</div>`;}

function progressionControl(room){
 if(room==='legacy'){const p=game.state.player,d=game.derived(),ready=p.legacy.generation>=2?Object.values(D.talents).filter(t=>game.talentPreview(t.id).eligible).length:0;return `<div class="progression-control ${ready?'is-ready':''}" aria-label="Legacy progression"><div class="progression-balance"><span>Legacy sparks</span><strong>${num(p.legacy.points)}</strong></div>${btn('Plan retirement →','modal',{modal:'retire'},!d.legacyEligible,'primary progression-upgrade')}<div class="progression-status ${ready?'can-upgrade':''}">${ready?ready+' permanent talents ready to learn':d.legacyEligible?'Retirement will earn '+d.legacyReward+' sparks':'Defeat the tier 5 boss in this generation to retire.'}</div></div>`;}

 if(room==='smith')return `<div class="smith-points" aria-label="Unspent attribute points"><span>Unspent attribute points</span><strong>${num(game.state.player.points)}</strong></div>`;
 const amount=game.currencies()[room],choices=Object.values(P.nodes).filter(n=>n.section===room).map(n=>({node:n,preview:game.treePreview(n.id)}));
 const ready=choices.filter(v=>v.preview.eligible).length,complete=choices.every(v=>v.preview.rank>=v.node.maxRank);
 const currency={mine:'Prospecting points',forge:'Gold available',shop:'Influence points',adventurers:'Merit points'}[room];
 const earn={mine:'Mine materials to earn Prospecting.',forge:'Sell equipment to fund your forge.',shop:'Equip customers to earn reputation.',adventurers:'Finish expeditions to earn Merits.'}[room];
 const status=ready?num(ready)+' upgrade'+(ready===1?'':'s')+' ready to buy':complete?'All upgrades fully developed':earn;
 return `<div class="progression-control ${ready?'is-ready':''}" aria-label="${title(room)} progression"><div class="progression-balance"><span>${currency}</span><strong>${num(amount)}</strong></div><button class="primary progression-upgrade" data-action="modal" data-modal="upgrades" aria-describedby="progression-hint"><span>${title(room)} upgrades</span><span aria-hidden="true">→</span></button><div class="progression-status ${ready?'can-upgrade':''}" id="progression-hint">${ready?'<span class="availability-dot" aria-hidden="true"></span>':''}${status}</div></div>`;
}

function roomToolbar(){const r=UI.room;return `<div class="room-toolbar progression-toolbar"><div class="room-title"><div><div class="eyebrow">${r==='legacy'?'THE MAKERS WHO CAME BEFORE':({starter:'HUMBLE BEGINNINGS',middle:'A GROWING REPUTATION',grand:'A LASTING LEGACY'})[EIRoomModel.stage(game,r)]}</div><h1>${EIRoomModel.roomName(game,r)}</h1></div>${r==='legacy'?'':`<div class="room-secondary-tools">${btn('Room growth','modal',{modal:'appearance'},false,'text-button room-growth-button')}</div>`}</div>${progressionControl(r)}</div>`;}

function followStrip(){const h=game.state.adventurers.find(h=>h.id===UI.followHero);if(!h)return '';const a=EIRoomModel.activity(game,h);return `<div class="follow-strip"><span class="live-dot"></span><strong>Following ${esc(h.name)}</strong><span>${EIRoomModel.labels[a.phase]||title(a.phase)} · view changes automatically</span>${btn('Stop following','stop-follow',{},false,'text-button')}</div>`;}
function roomContent(){if(UI.room==='legacy')return legacyDashboard();if(UI.room==='smith')return smithDashboard();if(UI.room==='mine')return mineDashboard();if(UI.room==='forge')return forgeDashboard();if(UI.room==='shop')return shopDashboard();return adventurerDashboard();}
function legacyDashboard(){const s=game.state,p=s.player,d=game.derived();return statTiles([['Generation',p.legacy.generation],['Sparks earned',num(p.legacy.totalPoints)],['Talents learned',p.talents.length+' / '+Object.keys(D.talents).length],['Designs remembered',Object.keys(p.legacy.collection).length]])+`<div class="legacy-overview"><section class="legacy-dedication"><div class="legacy-crest" aria-hidden="true">✧</div><div class="eyebrow">THE HALL OF LEGACIES</div><h2>The forge outlives<br>its maker.</h2><p>Every life leaves something in the fire. Carry your finest work, hard-won wisdom and permanent talents into the next generation.</p><div class="legacy-keeps"><div><strong>What endures</strong><p>Learned talents, unspent sparks, collection records, legacy recipes, furnishings and one protected heirloom.</p></div><div><strong>A fresh beginning</strong><p>Gold, materials, ordinary stock, smith attributes and proficiency, employees, heroes, quest progress and room upgrades reset.</p></div></div></section><aside>${panel('The next generation',`<div class="legacy-reward"><strong>${d.legacyEligible?'+'+d.legacyReward:'—'}</strong><span>sparks on retirement</span></div>${legacyBreakdown()}<p class="panel-note">${d.legacyEligible?'Your final victory has earned a place in this hall. Choose an heirloom before passing on the forge.':'The hall remains yours. To retire again, defeat the Void Sovereign in this generation.'}</p>`,btn('Plan retirement','modal',{modal:'retire'},!d.legacyEligible,'primary'))}${panel('The road remembered',`<div class="boss-milestones">${D.tierBosses.map(id=>`<span class="${s.questWins[id]?'won':''}">Tier ${D.quests[id].tier} ${s.questWins[id]?'✓':'◇'}</span>`).join('')}</div><p class="panel-note">One clear per tier boss. Repeat victories do not add retirement sparks.</p>`,btn('Collection','modal',{modal:'collection'}))}</aside></div><section class="legacy-talents"><div class="panel-heading"><h2>Four paths. A lasting advantage.</h2><span class="badge">24 permanent talents</span></div><p class="panel-note">${p.legacy.generation<2?'The talent tree opens after your first retirement. Preview your inheritance below.':'Each talent carries into every future generation. Invest your sparks down a branch to reveal its full strength.'}</p>${p.legacy.generation<2?`<div class="legacy-path-preview">${[...new Set(Object.values(D.talents).map(t=>t.branch))].map(branch=>{const first=Object.values(D.talents).find(t=>t.branch===branch);return `<article><span aria-hidden="true">◇</span><h3>${title(branch)}</h3><p>${first.description}</p><small>6 talents · unlocks after retirement</small></article>`;}).join('')}</div>`:legacyTree()}</section>`;}
function smithDashboard(){const s=game.state,p=s.player,d=game.derived();return statTiles([['Profession',P.professions[s.world.profession].name],['Smith level',p.level,`${num(p.xp)} / ${num(d.levelXpRequired)} XP`],['Attribute points',p.points,'5 gained per level'],['Crafted',num(s.stats.crafted)],['Reputation',num(p.reputation)],['Generation',p.legacy.generation]])+`<div class="dashboard-columns"><div>${panel('Your attributes',attributes()+`<p class="panel-note">${P.professions[s.world.profession].description}</p>`,btn('Full bonuses','modal',{modal:'smith'}))}${panel('People · workshop employees',staffPanel())}${panel('Furnishings · permanent upgrades',furnishingsPanel())}${panel('Class mastery',`<div class="proficiency-grid">${game.availableClasses().map(id=>`<div class="proficiency"><strong>${D.classes[id].name}<span class="mastery-number">${p.proficiency[id].level}</span></strong>${bar(p.proficiency[id].xp,6+2*p.proficiency[id].level)}<small>${Math.floor(p.proficiency[id].xp)} XP · next level ${6+2*p.proficiency[id].level}</small><small class="mastery-hint">${masteryHint(id)}</small></div>`).join('')}</div>`)}</div><aside>${panel('Your progression',`<div class="row"><strong>Smith level ${p.level}</strong><small>${num(p.xp)} / ${num(d.levelXpRequired)} XP</small></div>${bar(p.xp,d.levelXpRequired)}<p class="panel-note">Craft to earn experience. A standard pattern bridges the next material tier; prestige work rewards high attributes.</p><div class="info-pair"><span>Legacy readiness</span><strong>${d.legacyEligible?'Void Sovereign defeated':d.legacyBreakdown.bossesDefeated+' / 5 bosses'}</strong></div>`,btn('Open Legacy','room',{room:'legacy'},!EIRoomModel.legacyUnlocked(game)))}${panel('Workshop records',eventList(null,5),btn('Collection','modal',{modal:'collection'}))}</aside></div>`;}
function mineDashboard(){
 const s=game.state,w=s.world,d=game.derived(),points=EIWorldEngine.pointsFor(w.totalMined),seams=game.seams(),next=P.seams.find(v=>!seams.some(q=>q.id===v.id)),manual=game.quarryDerived();
 const workings=`<div class="workings-grid">${seams.map(v=>{
 const assigned=w.miners.filter(m=>m.assigned===v.id).length,working=w.miners.filter(m=>m.working===v.id).length,full=s.materials[v.id]>=game.binCapacity();
 return `<article class="working-card"><div class="working-heading"><span class="ore-symbol" style="color:${D.materials[v.id].color}">◆</span><div><h3>${v.name}</h3><small>${seconds(v.seconds/(1+(game._effects().miningSpeed||0)))} per worker load</small></div><span class="badge">${full?'Bin full':working+' working'}</span></div><div class="working-stock"><strong>${num(s.materials[v.id])}<small> / ${num(game.binCapacity())}</small></strong>${btn(full?'Bin full':manual.manualReady?'Mine':'Ready in '+seconds((s.quarry.nextManualAt-s.simTime)/1000),'mine',{material:v.id},!manual.manualReady||full,'primary')}</div>${bar(s.materials[v.id],game.binCapacity())}<div class="working-meta"><span>${assigned} assigned${working!==assigned?' · '+working+' here now':''}</span><span>${full?'Workers use another seam':'Materials in stock'}</span></div>${materialTrade(v.id)}</article>`;
 }).join('')}${next?`<article class="next-working"><div class="eyebrow">NEXT SEAM</div><strong>${next.name}</strong><p>${seamRequirement(next)}</p>${btn('View requirements','modal',{modal:'upgrades'},false,'text-button')}</article>`:''}</div>`;
 const workers=`<p class="panel-note">Workers keep their assignment. When a bin fills, they mine another open seam until there is room again.</p><div class="worker-assignment-grid">${w.miners.map(m=>`<article class="miner-card"><div class="row"><strong>Worker ${m.id.split('-')[1]}</strong><small>${Math.floor(m.progress*100)}%</small></div><small class="miner-current">${D.materials[m.working].name}${m.working!==m.assigned?' · covering a full bin':' · working'}</small>${bar(m.progress,1)}<label><span>Assigned seam</span><select aria-label="Worker ${m.id.split('-')[1]} assigned seam" data-worker="${m.id}">${seams.map(v=>`<option value="${v.id}" ${m.assigned===v.id?'selected':''}>${v.name}</option>`).join('')}</select></label></article>`).join('')}</div>`;
 return statTiles([['Prospecting',num(game.currencies().mine)],['Miners',`${w.miners.length} / ${d.workerCapacity}`],['Bin capacity',num(game.binCapacity()),'each material'],['Lifetime mined',num(w.totalMined)]])+`<div class="mine-workspace">${panel('Open workings',workings,'','mine-workings')}<aside class="room-sidebar mine-sidebar">${panel('Crafting supplies',supplyButtons(),'','supplies-panel')}${panel('Worker assignments',workers,btn('Hire · '+game.hireCost()+' Prospecting','hire',{},game.currencies().mine<game.hireCost()||w.miners.length>=d.workerCapacity),'mine-workforce')}</aside><section class="mine-prospecting"><div><strong>Next Prospecting point</strong><small>${num(points.progress)} / ${num(points.next)} extracted · ${num(points.next-points.progress)} to go</small></div>${bar(points.progress,points.next)}<p>Only extraction earns points. Trading, refunds and quest loot do not.</p></section></div>`;
}

function finishControl(j){const p=game.techniquePreview(j.id);return `<div class="finish-control"><small>${p.eligible?`+${p.qualityGain} quality · +10 pp prefix<br>+${seconds(p.addedSeconds)} work (+100%)${j.status==='queued'?' · estimated':''}`:j.status==='queued'?'Applies when work starts':'Included in time & quality'}</small>${btn(j.technique?'Finish selected':'Quality finish','technique',{id:j.id},!p.eligible)}</div>`;}
function compactQueue(){const s=game.state;return s.jobs.map(j=>`<div class="work-order"><div class="row"><strong>${D.recipes[j.recipeId].name}</strong><small>${j.status==='active'?seconds((j.completeAt-s.simTime)/1000):'Queued'}</small></div>${bar(j.status==='active'?s.simTime-j.startedAt:0,j.duration||1)}<small>${j.status==='active'?'Quality '+j.quality+' · '+Math.round((j.affixChance||0)*100)+'% prefix chance':'Materials reserved'}</small>${finishControl(j)}</div>`).join('')||'<p class="empty">No work queued. Choose a recipe to begin.</p>';}
function forgeDashboard(){const s=game.state,d=game.derived();return statTiles([['Active benches',`${s.jobs.filter(j=>j.status==='active').length} / ${d.stationCount}`],['Orders',`${s.jobs.length} / ${d.stationCount+d.queueCapacity}`],['Quality ceiling',d.qualityCap],['Warehouse',`${s.inventory.length} / ${d.storageCapacity}`],['Pieces crafted',s.stats.crafted]])+`<div class="dashboard-columns forge-columns ${s.jobs.length?'has-orders':''}"><div>${panel('Crafting catalogue','<p class="practice-note">Training gear is cheap. Standard patterns equip your company. Prestige patterns demand exceptional attributes and are optional on the path to the next tier.</p>'+forgeDock(),'', 'catalogue-panel')}${(game._effects().automation||s.staff.quartermaster)?panel('Production rules','<p class="panel-note">Repeat a selected pattern within your material budget.</p>',btn('Configure','modal',{modal:'automation'})):''}${panel('Installed machinery',`<div class="machine-list"><span>✓ Basic anvil</span>${[['grinder','Grinding stone'],['smelter','Smelting furnace'],['tempering','Tempering station'],['runeBench','Runic workbench'],['starforge','Starforge crucible']].filter(([id])=>game._effects()[id]).map(([,name])=>`<span>✓ ${name}</span>`).join('')}</div>`,btn('Develop the forge','modal',{modal:'upgrades'}))}</div><aside class="room-sidebar forge-sidebar">${panel('Crafting supplies',supplyButtons(),'','supplies-panel')}${panel('Work in progress',compactQueue(),btn('Manage queue','modal',{modal:'queue'}),'forge-work')}<details class="forge-materials info-panel" data-detail-key="forge-materials"><summary>Material stock</summary>${resourceList()}${btn('Open workings','room',{room:'mine'})}</details></aside></div>`;}
function quickHeroSummary(){return `<div class="customer-list">${game.state.adventurers.map(h=>{const a=EIRoomModel.activity(game,h);return `<button data-action="select-hero" data-id="${h.id}"><strong>${h.name}</strong><span>${EIRoomModel.labels[a.phase]||a.phase}</span><small>${a.remainingMs?seconds(a.remainingMs/1000):''}</small></button>`;}).join('')}</div>`;}
function cargoSummary(){return `<p class="panel-note">Full bins discard excess materials. There is no overflow storage. ${num(game.state.world.materialsLost||0)} materials lost this run.</p>`;}
function warehouseList(){const s=game.state,d=game.derived(),stock=s.inventory.filter(i=>!i.displayed).sort((a,b)=>a.quality-b.quality||(a.createdAt||0)-(b.createdAt||0)||a.id.localeCompare(b.id)),displayFull=s.inventory.filter(i=>i.displayed).length>=d.displayCapacity;return `<p class="warehouse-summary">${stock.length} stored · ${s.inventory.length} / ${d.storageCapacity} total items, including displays</p>${stock.length?`<ul class="warehouse-list" aria-label="Stored equipment">${stock.map(i=>{const r=D.recipes[i.recipeId],sale=game.salePreview(i.id);return `<li class="warehouse-row ${quality(i.quality)}"><button class="warehouse-open" data-action="item" data-id="${i.id}">${icon(r.classId)}<span><strong>${esc(itemName(i))}</strong><small><i class="material-dot" style="background:${D.materials[r.materialId].color}"></i>${esc(D.materials[r.materialId].name)} · Q${i.quality} ${quality(i.quality)} · ${i.protected?'Protected':i.reservedFor?'Reserved':i.autoDisplayHold?'Held':'Awaiting display'}</small></span></button><div class="warehouse-actions">${btn('Display','display',{id:i.id},displayFull)}${btn('Sell '+sale.price+'g','town-sell',{id:i.id},!sale.eligible)}${btn('Scrap','salvage',{id:i.id},game._protected(i))}</div></li>`;}).join('')}</ul>`:'<p class="empty">No stored equipment. Finished pieces fill empty displays first.</p>'}<small class="warehouse-note">Open displays fill automatically, lowest quality first. Auto-fill skips held, protected and reserved pieces.</small>`;}
function autoSalvageControls(){if(!game._effects().autoScrap)return '';return `<div class="policy-box"><h3>Automatic salvage</h3><p>Only unprotected, unreserved warehouse items are scrapped. Displayed items are safe.</p><label><input type="checkbox" id="auto-scrap" ${game.state.world.policy.autoScrap?'checked':''}> Enable automatic salvage</label><div class="salvage-threshold"><label>Below quality <input id="scrap-quality" type="number" min="0" max="200" step="1" value="${esc(UI.scrapQuality??game.state.world.policy.scrapQuality)}"></label>${btn('Apply threshold','scrap-threshold')}</div><small>Saved threshold: below Q${game.state.world.policy.scrapQuality}. Changes take effect when applied.</small></div>`;}
function shopDashboard(){const s=game.state,d=game.derived(),customers=s.adventurers.filter(h=>['browsing','ready'].includes(h.status)),stock=s.inventory.filter(i=>i.displayed);return statTiles([['Displayed',`${stock.length} / ${d.displayCapacity}`],['Storage used',`${s.inventory.length} / ${d.storageCapacity}`],['Browsing',customers.length],['Items sold',s.stats.sold],['Influence',num(game.currencies().shop)]])+`<div class="dashboard-columns shop-columns"><div class="shop-stock">${panel('Items for sale',`<div class="shelf-grid">${stock.map(i=>itemCard(i,true)).join('')}${Array.from({length:Math.max(0,d.displayCapacity-stock.length)},(_,i)=>`<div class="empty-display"><span>◇</span><strong>Display ${stock.length+i+1}</strong><small>Empty · fills automatically</small></div>`).join('')}</div>`)}${panel('Warehouse',warehouseList(),'','warehouse-panel')}</div><aside>${panel('Customer requests',requestList().map(c=>`<div class="work-order"><strong>${esc(s.adventurers.find(h=>h.id===c.heroId)?.name)} · ${D.classes[c.classId].name}</strong><small>Tier ${c.minTier}+ · quality ${c.minQuality}+ · premium ×${c.premium}</small></div>`).join('')||'<p class="panel-note">No craftable requests yet. Useful sales build relationships; new patterns and mastery open more requests.</p>')}${panel('In the shop now',`<div class="customer-list">${customers.map(h=>`<button data-action="select-hero" data-id="${h.id}"><strong>${esc(h.name)}</strong><span>${esc(h.shoppingReason)}</span><small>${h.budget}g budget · relationship ${h.relationship}</small></button>`).join('')||'<p class="empty">Your company is adventuring or recovering.</p>'}</div>`)}</aside></div>`;}

function heroStatus(h){const a=EIRoomModel.activity(game,h);return EIRoomModel.labels[a.phase]||title(a.phase);}
function heroPortrait(h){return `<span class="hero-seal ${h.archetypeId}">${icon((P.access[h.archetypeId]||[])[0])}</span>`;}
function formationHealth(units,cls){return `<div class="formation-health">${['front','back'].map(line=>`<section><h4>${line==='front'?'Front line':'Back line'}</h4>${units.filter(u=>(u.line||'front')===line).map(u=>`<div><span>${esc(u.name)}<b>${Math.ceil(u.hp)} / ${Math.ceil(u.maxHp)}</b></span>${bar(u.hp,u.maxHp,cls)}</div>`).join('')||'<small>No units</small>'}</section>`).join('')}</div>`;}
function heroViewer(h){
 if(!h)return '<p class="empty">Select a hero to watch.</p>';
 const s=game.state,a=EIRoomModel.activity(game,h),r=s.runs.find(r=>r.id===a.runId),v=r?game.battleView(r.id):null,status=heroStatus(h),q=D.quests[a.questId];
 return `<div class="hero-viewer"><div class="viewer-heading"><div>${heroPortrait(h)}<span><h2>${esc(h.name)}</h2><small>${D.archetypes[h.archetypeId].name} · level ${h.level} · ${D.archetypes[h.archetypeId].line} line</small></span></div><div class="viewer-heading-actions"><span class="live-indicator">● ${status}</span>${btn(UI.followHero===h.id?'Following hero':'Follow hero','follow-hero',{id:h.id},UI.followHero===h.id,'primary')}</div></div><div class="hero-stage ${a.phase}" data-hero-id="${h.id}"><canvas id="hero-canvas" aria-label="Live view of ${esc(h.name)}"></canvas><div class="stage-caption"><strong>${a.room==='shop'?'Browsing your displays':a.phase==='recovering'?'Recovery quarters':q?.name||'Roadside inn'}</strong><span>${a.remainingMs>0?seconds(a.remainingMs/1000)+' · '+(a.phase==='recovering'?'until recovered':a.room==='shop'?'browsing time':a.phase==='travelling'?'until encounter':a.phase==='fighting'?'until battle ends':'until home'):status}</span></div></div><div class="journey-steps">${[['shop','Shop'],['travelling','Travel'],['fighting','Battle'],['returning','Home'],['recovering','Rest']].map(([phase,label])=>`<span class="${(phase==='shop'?a.room==='shop':a.phase===phase)?'current':''}">${label}</span>`).join('')}</div>${v?`<details class="hero-battle-detail" data-detail-key="${h.id}-${r.id}-combat"><summary>Round ${v.round} / ${v.rounds} · ${v.victory===true?'Victory':v.victory===false?'Retreat':'Live battle details'}</summary>${v.victory!==null?`<p class="quest-outcome ${v.victory?'result-win':'result-loss'}">${v.victory?'Victory. Rewards are on their way home.':'Retreat. Equipment is kept; the party will rest and look for upgrades.'}</p>`:''}<p class="panel-note">The front line protects the rear.</p><div class="combat-health">${formationHealth(v.heroes,'health')}${formationHealth(v.enemies,'enemy-health')}</div><div class="live-combat-log" aria-live="polite">${v.events.slice(-3).map(event=>`<p>${esc(event.text||'The encounter continues.')}</p>`).join('')||'<p>On the way to the encounter.</p>'}</div>${btn('Detailed combat log','watch',{id:r.id},false,'text-button')}</details>`:`<p class="viewer-reason">${esc(h.shoppingReason||'Preparing for the next adventure.')}</p>`}</div>`;
}

function nextRecipePanel(){const materialNames=new Set(Object.values(D.materials).map(m=>m.name)),next=Object.values(D.recipes).filter(r=>r.classId===UI.type&&r.variant!==2).sort((a,b)=>a.tier-b.tier||(a.variant||0)-(b.variant||0)).find(r=>game.craftPreview(r.id).gates.some(g=>!materialNames.has(g.label)&&!g.met));if(!next)return '<p class="practice-note">All standard patterns are unlocked. Prestige patterns appear when their higher attributes and mastery are met.</p>';const v=game.craftPreview(next.id),missing=v.gates.filter(g=>!g.met).map(g=>{const station=Object.entries(next.requires.upgrades||{}).find(([id])=>Object.values(D.classes).some(c=>c.station===id)&&D.upgrades[id]?.name===g.label);return station?{...g,label:P.nodes['forge_machinery_'+station[1]]?.name||g.label,current:0,required:1}:g;});return `<section class="next-pattern"><div><div class="eyebrow">NEXT PATTERN · TIER ${next.tier}</div><strong>${next.name}</strong><p>${next.description}</p></div><ul>${missing.map(g=>`<li><strong>${title(g.label)}:</strong> ${g.label==='Recipe discovery'?esc(g.source):num(g.current)+' / '+num(g.required)}</li>`).join('')}</ul></section>`;}
function bossBoard(){const s=game.state,bosses=D.tierBosses.map(id=>D.quests[id]),next=bosses.find(q=>!s.questWins[q.id]),q=next||bosses.at(-1),missing=game._gates(q.requires).filter(g=>!g.met),target=D.quests[s.world.bossTarget],active=s.runs.some(r=>r.questId===q.id&&!['complete','pending'].includes(r.status));return panel('Tier bosses',`<div class="boss-milestones">${bosses.map(b=>`<span class="${s.questWins[b.id]?'won':b.id===q.id?'current':''}">Tier ${b.tier} ${s.questWins[b.id]?'✓':'◇'}</span>`).join('')}</div><div class="tier-route" aria-label="Tier ${q.tier} quest levels">${D.questTiers[q.tier-1].slice(0,3).map(id=>{const level=D.quests[id],wins=s.questWins[id]||0;return `<div class="${wins>=5?'cleared':''}"><strong>Level ${level.questLevel}</strong><span>${level.name}</span><b>${Math.min(5,wins)} / 5</b></div>`;}).join('')}</div><div class="boss-preview"><div><h3>${q.name}</h3><p>${q.tier<5?'Defeat this boss to open tier '+(q.tier+1)+' quests.':'Defeat the final boss to unlock Legacy retirement.'} Choose ${q.minPartySize}–3 heroes.</p><small>${missing.length?missing.map(g=>`${g.label}: ${g.current} / ${g.required}`).join(' · '):'Approach cleared. Your party can challenge this boss.'}</small></div>${btn(active?'Boss expedition underway':'Select boss party','boss-party',{id:q.id},missing.length>0||active,'primary')}</div>${target?`<div class="gathering-party"><strong>Gathering for ${target.name}</strong><small>${s.world.bossAutoLaunch?'Automatic launch once everyone is recovered and a slot is free.':'Party held. Open Edit party and choose Gather and launch to depart.'}</small><p>${s.world.bossParty.map(id=>{const h=s.adventurers.find(h=>h.id===id);return h.name+': '+(['browsing','ready'].includes(h.status)?'ready at shop':heroStatus(h));}).join(' · ')}</p>${btn('Edit party','boss-party',{id:target.id},false,'primary')}${btn('Cancel gathering','release-boss')}</div>`:''}`);}
function bossThreats(q,ids){const types=[...new Set(q.enemies.map(e=>e.damageType||'physical'))],elements=types.filter(t=>t!=='physical');return `<div class="boss-threats"><h3>Encounter & protection</h3><p>${q.enemies.map(e=>`${esc(e.name)}: ${Math.round(e.health)} health · ${e.attack} ${title(e.damageType||'physical')} attack · ${e.armor} armour${e.phaseName?' · '+esc(e.phaseName)+' below '+Math.round(e.phaseAt*100)+'% health':''}`).join('<br>')}</p>${ids.map(id=>{const h=game.state.adventurers.find(h=>h.id===id),st=game.heroStats(id);return `<small>${h.name}: ${Math.round(st.health)} health · ${st.armor.toFixed(1)} armour${elements.map(t=>' · '+Math.round((st.resistances[t]||0)*100)+'% '+title(t)+' resistance').join('')}</small>`;}).join('')}<p class="muted">${elements.length?'Matching enchanted wards reduce elemental damage. Complete armour and accessories before risking the party.':'Armour, health and a full loadout help the party survive. Heavy weapons help against armour.'}</p></div>`;}
function bossPartyModal(){const q=D.quests[UI.id];if(!q?.manualBoss)return '<p>Choose a tier boss from the Adventurers room.</p>';const s=game.state,ids=UI.bossHeroes||[],v=game.questPreview(q.id,ids),gathering=s.world.bossTarget===q.id,armed=gathering&&s.world.bossAutoLaunch&&ids.length===s.world.bossParty.length&&ids.every(id=>s.world.bossParty.includes(id)),blocked=ids.length<q.minPartySize||ids.length>3||game._gates(q.requires).some(g=>!g.met)||s.runs.some(r=>r.questId===q.id&&!['complete','pending'].includes(r.status));return `<p>${q.description}</p><p class="practice-note">Select ${q.minPartySize}–3 heroes, then Gather and launch. They finish their journeys, recover and wait at the shop. The expedition launches automatically once everyone is ready and a slot is free.</p><div class="boss-party-list">${s.adventurers.map(h=>`<label class="boss-party-choice"><input type="checkbox" data-boss-hero="${h.id}" ${ids.includes(h.id)?'checked':''}><span><strong>${esc(h.name)} · ${D.archetypes[h.archetypeId].name} · level ${h.level}</strong><small>${heroStatus(h)} · ${h.equipment.weapon?esc(itemName(h.equipment.weapon)):'Worn starting weapon'}</small></span></label>`).join('')}</div>${bossThreats(q,ids)}<div class="boss-forecast"><strong>${ids.length} / 3 selected · ${ids.length?v.successEstimate+'% estimated success':'select heroes'}</strong><p>${v.eligible?'Ready to depart immediately. Outcomes depend on equipment and combat.':esc(v.reason)}</p><small>${v.gates.filter(g=>!g.met).map(g=>`${g.label}: ${g.current} / ${g.required}`).join(' · ')}</small></div><div class="row boss-actions">${btn(armed?'Gathering party…':'Gather and launch','gather-launch-boss',{id:q.id},blocked||armed,'primary')}${gathering?btn('Cancel gathering','release-boss'):''}</div>`;}

function heroQuestPanel(h,showBosses=true){
 const a=EIRoomModel.activity(game,h),q=D.quests[a.questId||h.questId],memories=h.memories||[];
 return `<section class="hero-quest-journal"><div class="row"><h3>Quests & recent adventures</h3><span class="badge">${num(h.relationship)} relationship · ${num(h.failures||0)} retreats</span></div><p class="current-quest"><strong>${q?esc(q.name)+' · Tier '+q.tier+' / '+(q.manualBoss?'Boss':'Level '+q.questLevel):'Preparing for the next quest'}</strong><span>${heroStatus(h)}${a.remainingMs?' · '+seconds(a.remainingMs/1000)+' remaining':''}</span></p><div class="quest-journal-columns">${questBoard()}<div class="hero-adventure-history"><h4>${esc(h.name)}’s recent adventures</h4><ol>${memories.slice(0,8).map(m=>{const quest=D.quests[m.questId];return `<li><span class="history-result result-${m.victory?'win':'loss'}">${m.victory?'Victory':'Retreat'}</span><div><strong>${esc(quest?.name||'Expedition')}</strong><small>Tier ${quest?.tier||1} · ${quest?.manualBoss?'Boss':'Level '+(quest?.questLevel||1)} · ${seconds((game.state.simTime-m.time)/1000)} ago</small></div></li>`;}).join('')||'<li class="empty">Their first story is still ahead.</li>'}</ol></div></div>${showBosses?bossBoard():''}</section>`;
}
function adventurerDashboard(){
 const s=game.state,heroes=s.adventurers;if(!heroes.some(h=>h.id===UI.selectedHero))UI.selectedHero=heroes[0]?.id;
 const h=heroes.find(h=>h.id===UI.selectedHero);
 return `<div class="adventure-workspace"><aside class="info-panel roster-panel"><div class="panel-heading"><h2>Your company</h2>${btn('Policies','modal',{modal:'policies'})}</div><div class="hero-roster">${heroes.map(hero=>{const activity=EIRoomModel.activity(game,hero);return `<button class="roster-row ${UI.selectedHero===hero.id?'selected':''}" data-action="select-hero" data-id="${hero.id}" aria-pressed="${UI.selectedHero===hero.id}">${heroPortrait(hero)}<span><strong>${esc(hero.name)}<small>Lv ${hero.level}</small></strong><small class="roster-class">${D.archetypes[hero.archetypeId].name} · ${D.archetypes[hero.archetypeId].line} line</small><span>${heroStatus(hero)}</span><small>${activity.remainingMs?seconds(activity.remainingMs/1000):D.archetypes[hero.archetypeId].name}${UI.followHero===hero.id?' · following':''}</small></span></button>`;}).join('')}</div><div class="company-tools">${btn('Hire heroes','modal',{modal:'recruitment'})}${btn('Tier bosses','modal',{modal:'bosses'})}</div><dl class="company-summary">${[['Recruited',heroes.length],['Questing',heroes.filter(h=>['travelling','fighting','returning'].includes(h.status)).length],['Recovering',heroes.filter(h=>h.status==='recovering').length],['Victories',num(s.stats.questsWon)],['Retreats',num(s.stats.questsLost)],['Merits',num(game.currencies().adventurers)]].map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl><p class="panel-note">Follow a hero between the shop, quests and recovery.</p></aside><section class="info-panel selected-hero">${heroViewer(h)}${h?heroStatsPanel(h)+heroEquipTypes(h)+heroEquipmentPanel(h)+heroQuestPanel(h):''}</section></div>`;
}

function render(){
 const active=document.activeElement;
 if(UI.room==='legacy'&&!EIRoomModel.legacyUnlocked(game))UI.room='smith';
 if(!game.state.started&&UI.room!=='legacy'){UI.followHero=null;if(!$('.creation'))$('#app').innerHTML=creation();return;}
 if(UI.followHero&&!UI.modal){const next=EIRoomModel.followRoom(game,UI.followHero);if(next){UI.room=next;UI.selectedHero=UI.followHero;}else UI.followHero=null;}
 const current=$('.world');
 if(!$('.topbar')||current?.dataset.room!==UI.room){$('#app').innerHTML=header()+scene();window.scrollTo({top:0,left:0,behavior:'instant'});}
 else {element($('.topbar'),header());if(current.dataset.art!==EIRoomModel.artKey(game,UI.room)){current.style.setProperty('--room-art',`url('${art(UI.room)}')`);current.dataset.art=EIRoomModel.artKey(game,UI.room);}element($('.room-toolbar'),roomToolbar());element($('.objective-strip'),objectiveStrip());content($('.follow-holder'),followStrip());content($('.room-body'),roomContent());}
 $('.world-footer>span').textContent=UI.readonly?'Viewing only - another tab is running this workshop':storageError||'Progress saved automatically - adventurers act on their own';
 EIWorldScenes.bindHero($('#hero-canvas'),game,UI.selectedHero,UI.reduced);
 if(active?.id&&document.getElementById(active.id))document.getElementById(active.id).focus({preventScroll:true});
}


function overlay(name,content,wide=false){return `<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><header class="modal-header"><div><div class="eyebrow">EMBER & IRON · ${title(UI.room)}</div><h2 id="modal-title">${name}</h2></div>${btn('×','close',{},false,'close-button')}</header><div class="modal-body">${content}</div></section></div>`;}

function open(modal,id){if(modal==='legacy'){if(EIRoomModel.legacyUnlocked(game)){UI.room='legacy';UI.followHero=null;close();render();}return;}modalFocus=document.activeElement;UI.modal=modal;UI.id=id;UI.scrapQuality=null;modalStamp='';renderModal();$('.modal').focus();}

function legacyTree(){const p=game.state.player;return `<div class="legacy-grid">${[...new Set(Object.values(D.talents).map(t=>t.branch))].map(branch=>`<section class="legacy-branch"><h3>${title(branch)}</h3>${Object.values(D.talents).filter(t=>t.branch===branch).map(t=>{const v=game.talentPreview(t.id);return `<article class="tree-node ${p.talents.includes(t.id)?'learned':''}"><h4>${t.name}</h4><p>${t.description}</p><small>${t.previousId?'Requires '+D.talents[t.previousId].name:'Starting talent'}</small>${btn(p.talents.includes(t.id)?'Learned':t.cost+' sparks','talent',{id:t.id},!v.eligible)}<small>${v.reason}</small></article>`;}).join('')}</section>`).join('')}</div>`;}
function renderModal(){if(!UI.modal){$('#modal-root').innerHTML='';return;}const s=game.state,p=s.player,e=game._effects(),d=game.derived();let name='',html='',wide=false;

if(UI.modal==='recruit'){name='Welcome a new hero';html=`<p>Recruitment charter paid. Choose this hero’s identity and role.</p><label class="field">Hero name<input id="recruit-name" maxlength="28" value="${esc(UI.recruitName||'')}"></label><label class="field">Class<select id="recruit-class">${Object.values(D.archetypes).map(a=>`<option value="${a.id}" ${a.id===UI.recruitClass?'selected':''}>${a.name} · ${a.line} line</option>`).join('')}</select></label><p>${(P.access[UI.recruitClass]||[]).map(id=>D.classes[id].name).join(' · ')}</p>${btn('Hire hero','confirm-recruit',{id:UI.id},!UI.recruitName?.trim(),'primary')}`;}
if(UI.modal==='appearance'){name=title(UI.room)+' · room growth';wide=true;const current=EIRoomModel.stage(game,UI.room);html=`<p class="panel-note">Rooms grow with your accomplishments. Grand rooms require a later Legacy generation and deep progress in that run. Appearance does not change production.</p><div class="room-growth-grid">${EIRoomModel.progress(game,UI.room).map(stage=>`<section class="growth-stage ${stage.id===current?'current':''}"><span class="badge">${stage.id===current?'Current scene':stage.met?'Reached':'Not yet reached'}</span><h3>${stage.name}</h3><p>${{starter:'Humble beginnings',middle:'An established workshop',grand:'A lasting Legacy'}[stage.id]}</p>${stage.gates.length?`<ul>${stage.gates.map(g=>`<li class="${g.met?'met':''}"><span>${g.met?'✓':'◇'} ${g.label}</span><strong>${num(Math.min(g.current,g.required))} / ${num(g.required)}</strong></li>`).join('')}</ul>`:'<p>Every new run begins with the basic workshop.</p>'}</section>`).join('')}</div>`;}
if(UI.modal==='upgrades'){name=title(UI.room)+' development';wide=true;const nodes=Object.values(P.nodes).filter(n=>n.section===UI.room),bs=[...new Set(nodes.map(n=>n.branch))];html=`<div class="tree-intro"><div><strong>${num(game.currencies()[UI.room])} ${P.currencies[UI.room]} available</strong><p>${{mine:'Earn points by extracting materials. Each new point needs five more materials than the last. Purchases and recovered materials do not count.',forge:'Invest gold from your work. Each rank costs 90% more; deeper machines demand larger investments.',shop:'Invest reputation as Influence. Your lifetime reputation is preserved for discoveries and quest access.',adventurers:'Every completed expedition earns a Merit, including retreats. Better equipment remains the heart of success.'}[UI.room]}</p></div><span class="badge">24 upgrades · 3 paths</span></div><div class="upgrade-tree">${bs.map(b=>`<section class="tree-branch"><h3>${b}</h3>${nodes.filter(n=>n.branch===b).map(n=>{const v=game.treePreview(n.id);return `<article class="tree-node ${v.rank?'learned':''} ${v.eligible?'available':''}"><div class="row"><h4>${n.name}</h4><span>${v.rank} / ${n.maxRank}</span></div><p>${n.description}</p><small>${n.parents.length?'Requires '+n.parents.map(id=>P.nodes[id].name).join(' + '):'Starting branch'}</small>${btn(v.rank===n.maxRank?'Fully developed':num(v.cost)+' '+P.currencies[n.section]+' · '+(v.rank?'Improve':'Develop'),'tree',{id:n.id},!v.eligible,v.eligible?'primary':'')}<small class="node-reason">${v.eligible?'':v.reason}</small></article>`;}).join('')}</section>`).join('')}</div>${UI.room==='shop'?autoSalvageControls():''}`;}

if(UI.modal==='smith'){name='The maker’s journal';wide=true;html=`<div class="journal-grid"><section><div class="row"><h3>Your attributes</h3><span class="badge">${p.points} points available</span></div>${attributes()}${btn('Retrain attributes · '+(s.stats.crafted&&!p.respecTokens?'200g':'free'),'respec')}</section><section><div class="profession-note"><div class="eyebrow">${P.professions[s.world.profession].name}</div><h3>${P.professions[s.world.profession].title}</h3><p>${P.professions[s.world.profession].description}</p></div><h3>What your attributes do</h3><div class="effect-list"><p><b>Strength</b> adds ${(7*Math.sqrt(p.stats.strength-2)).toFixed(1)}% craft speed, improves heavy pieces and increases capacity.</p><p><b>Precision</b> contributes ${(6*Math.sqrt(p.stats.precision-1)).toFixed(1)} quality, plus ${(Math.min(55,10+.8*(p.stats.precision-2)+(e.affixChance||0)*100)).toFixed(1)}% total affix chance.</p><p><b>Charisma</b> gives ${(100*(d.priceMultiplier-1)).toFixed(1)}% total sale bonus and lets customers afford better work.</p><p><b>Knowledge</b> contributes ${(4*Math.sqrt(p.stats.knowledge-1)).toFixed(1)} quality; proficiency XP +${((.06*(p.stats.knowledge-2)+(e.proficiencyXp||0))*100).toFixed(0)}%; enchantment strength ×${d.enchantStrength.toFixed(2)}.</p></div><p class="muted">Attributes and smith levels have no gameplay cap. Speed, prices and quality use diminishing returns. Quality requires breakthroughs to exceed 100, up to 200.</p></section></div><div class="row">${btn('Workshop staff & furnishings','modal',{modal:'estate'})}${btn('Collection records','modal',{modal:'collection'})}</div><h3>Class proficiency</h3><div class="proficiency-grid">${game.availableClasses().map(id=>`<div class="proficiency"><strong>${D.classes[id].name}<span>${p.proficiency[id].level}</span></strong>${bar(p.proficiency[id].xp,6+2*p.proficiency[id].level)}<small>${Math.floor(p.proficiency[id].xp)} / ${6+2*p.proficiency[id].level} XP · ${p.proficiency[id].level>=25?'Bronze practice earns reduced XP':'Every piece improves this class'}</small></div>`).join('')}</div>`;}

if(UI.modal==='workers'){name='Assign your mining crew';html=`<p>Workers prefer their assigned seam. If its bin fills, they work another open seam and return as soon as there is room.</p><div class="row"><span>${s.world.miners.length} / ${d.workerCapacity} workers</span>${btn('Hire · '+game.hireCost()+' Prospecting','hire',{},game.currencies().mine<game.hireCost()||s.world.miners.length>=d.workerCapacity,'primary')}</div>${s.world.miners.map(m=>`<div class="worker-row"><div><strong>Worker ${m.id.split('-')[1]}</strong><small>Currently mining ${D.materials[m.working].name}${m.working!==m.assigned?' · temporary overflow assignment':''}</small>${bar(m.progress,1)}</div><label>Assigned seam<select data-worker="${m.id}">${game.seams().map(v=>`<option value="${v.id}" ${m.assigned===v.id?'selected':''}>${v.name}</option>`).join('')}</select></label></div>`).join('')}<p class="muted">No wages. Improve the mine to increase yield, crew capacity and extraction speed.</p>`;}

if(UI.modal==='market'){UI.room='mine';close();render();return;}

if(UI.modal==='queue'){name='At the anvil';html=`<p>${s.jobs.length} / ${d.queueCapacity+d.stationCount} work slots · ${d.stationCount} simultaneous benches. Materials are reserved when queued.</p><p class="practice-note">Quality finishing doubles total work time and adds +20 quality (up to your forge ceiling) and +10 percentage points prefix chance. Select once on active or queued work; queued estimates update when work begins.</p>${s.jobs.map(j=>`<article class="queue-card"><div class="row"><strong>${D.recipes[j.recipeId].name}</strong><span>${j.status==='active'?seconds((j.completeAt-s.simTime)/1000):'Queued'}</span></div>${bar(j.status==='active'?s.simTime-j.startedAt:0,j.duration||1)}<small>${j.status==='active'?'Quality '+j.quality+' · '+Math.round((j.affixChance||0)*100)+'% prefix chance':'Waiting for a bench'}</small>${finishControl(j)}<div class="queue-refund">${btn('Cancel & refund','cancel',{id:j.id},!game.cancellationPreview(j.id).eligible)}<small>${esc(game.cancellationPreview(j.id).reason)} Refund: ${Object.entries(j.inputs).map(([id,n])=>n+' '+D.materials[id].name).join(', ')}</small></div></article>`).join('')||'<div class="empty">The forge is quiet. Choose a recipe from the catalogue below.</div>'}`;}


if(UI.modal==='item'){const i=s.inventory.find(i=>i.id===UI.id);if(!i){const sale=s.shopEvents.find(ev=>ev.type==='purchase'&&ev.itemId===UI.id);if(!sale){close();return;}name='Purchased by an adventurer';html='<p>'+esc(s.adventurers.find(h=>h.id===sale.heroId)?.name||'An adventurer')+' bought this piece while you were viewing it.</p>';}else{const r=D.recipes[i.recipeId];name=itemName(i);html=itemCard(i)+`<div class="row item-actions">${btn(i.displayed?'Move to warehouse':'Put on display','display',{id:i.id})}${btn(i.protected?'Unprotect':'Protect','protect',{id:i.id})}${btn('Sell to town · '+game.salePreview(i.id).price+'g','town-sell',{id:i.id},!game.salePreview(i.id).eligible)}${btn('Salvage materials','salvage',{id:i.id},game._protected(i))}</div><h3>Crafted prefix & enchanted suffix</h3><p>${i.affixId?D.affixes[i.affixId].name+': '+D.affixes[i.affixId].description:'No crafted prefix. Precision improves the chance of a prefix on new crafts.'}</p><p>${i.enchantmentId?D.enchantments[i.enchantmentId].suffix+': '+D.enchantments[i.enchantmentId].description:'No enchanted suffix. Enchant at the Runic workbench; enchanting keeps the crafted prefix.'}</p><p class="panel-note">Quality grades use a fixed 200-point scale: Fine 45, Superior 80, Masterwork 115, Epic 150, Legendary 180.</p><h3>Combat contribution</h3><p>${Object.entries(game.itemStats(i.id)||{}).filter(([k,v])=>typeof v==='number'&&v).map(([k,v])=>title(k)+' '+v.toFixed(2)).join(' · ')}</p><h3>Enchantments</h3>${e.runeBench?Object.values(D.enchantments).map(en=>{const v=game.enchantPreview(i.id,en.id);return `<div class="market-row"><div><strong>${en.name}</strong><small>${esc(v.reason)}</small></div>${btn('Enchant','enchant',{id:i.id,enchantment:en.id},!v.eligible)}</div>`;}).join(''):'<p class="muted">Develop the Runic workbench in Forge → Machinery to enchant your pieces.</p>'}`;}}


if(UI.modal==='policies'){name='The company charter';html=`<p>Heroes browse, buy, choose quests, retreat, rest and retry automatically. Set their overall approach here.</p><div class="policy-options">${[['balanced','Balanced','Pursue reachable discoveries, then reliable quests.'],['solo','Independent','Travel alone; each hero chooses their own road.'],['cautious','Cautious','Prefer quests with at least an 80% estimated chance.'],['bold','Bold','Attempt new challenges from a 25% estimated chance.']].map(([id,label,text])=>btn(`<strong>${label}</strong><small>${text}</small>`,'party',{value:id},['cautious','bold'].includes(id)&&!e.partyPolicy,s.world.policy.party===id?'selected':'')).join('')}</div><p class="muted">Companion charter unlocks pairs and advanced policies; Warband charter unlocks parties of three.</p>`;}

if(['heroes','hero'].includes(UI.modal)){name='Adventurer records';wide=true;const hs=UI.id&&UI.modal==='hero'?s.adventurers.filter(h=>h.id===UI.id):s.adventurers;html=`<div class="hero-records">${hs.map(h=>heroCard(h)+(UI.modal==='hero'?heroStatsPanel(h)+heroEquipTypes(h)+heroEquipmentPanel(h)+heroQuestPanel(h,false):'')).join('')}</div>`;}
if(UI.modal==='recruitment'){name='Hire your company';html=recruitmentPanel();}
if(UI.modal==='bosses'){name='Tier bosses';wide=true;html=bossBoard();}

if(UI.modal==='boss'){name='Choose your boss party';wide=true;html=bossPartyModal();}

if(UI.modal==='quests'){name='The expedition map';wide=true;html=`<div class="quest-grid">${Object.values(D.quests).filter(q=>s.unlocks.quests.includes(q.id)).map(q=>`<article class="queue-card"><div class="eyebrow">TIER ${q.tier} · ${q.manualBoss?'BOSS':'LEVEL '+q.questLevel} · ${esc(q.regionId)}</div><h3>${q.name}</h3><p>${q.description}</p><small>${s.questWins[q.id]||0} victories · ${seconds(q.baseSeconds/(1+(e.travel||0)))} base quest time</small></article>`).join('')}</div>`;}

if(UI.modal==='watch'){const r=s.runs.find(r=>r.id===UI.id),v=r&&game.battleView(r.id);name=r?D.quests[r.questId].name:'Expedition';wide=true;html=!v?'<p>This adventure has finished.</p>':`<div class="battle-stage"><div class="battle-party">${v.heroes.map(h=>`<div class="battle-unit"><span>⚔</span><strong>${h.name}</strong>${bar(h.hp,h.maxHp,'health')}<small>${Math.ceil(h.hp)} / ${Math.ceil(h.maxHp)} health</small></div>`).join('')}</div><div class="battle-centre"><div class="eyebrow">${r.status}</div><strong>${v.victory===true?'VICTORY':v.victory===false?'RETREAT':r.status==='fighting'?'CLASH OF STEEL':'ON THE ROAD'}</strong><p>${seconds(v.returnIn/1000)} until home</p></div><div class="battle-party enemies">${v.enemies.map(h=>`<div class="battle-unit"><span>◆</span><strong>${h.name}</strong>${bar(h.hp,h.maxHp,'enemy-health')}<small>${Math.ceil(h.hp)} / ${Math.ceil(h.maxHp)} health</small></div>`).join('')}</div></div><div class="battle-events" aria-live="polite">${v.events.slice(-5).map(event=>`<p>${esc(event.text||'Steel meets steel.')}</p>`).join('')||'<p>The party is making its way to the encounter.</p>'}</div>`;}


if(UI.modal==='retire'){name='Pass on the forge';html=`<p>This begins a new generation and resets the workshop economy, workers, heroes and room upgrades. Your Legacy gains <b>${d.legacyReward} sparks</b>.</p>${legacyBreakdown()}<label class="field">Choose an heirloom<select id="heirloom"><option value="">No heirloom</option>${s.inventory.filter(i=>i.protected).map(i=>`<option value="${i.id}">${esc(itemName(i))} · Q${i.quality}</option>`).join('')}</select></label><p class="muted">Protect a piece in the warehouse to make it available here.</p>${btn('Retire and begin a new generation','retire',{},!d.legacyEligible,'primary')}`;}

if(UI.modal==='estate'){name='Workshop employees & furnishings';wide=true;html=staffPanel()+furnishingsPanel();}

if(UI.modal==='collection'){name='A lifetime of work';wide=true;html=`<p>Every recipe remembers your best quality across generations.</p><div class="proficiency-grid">${Object.entries(p.legacy.collection).map(([id,q])=>`<article class="proficiency"><strong>${D.recipes[id].name}<span>Q${q}</span></strong><small>${quality(q)}</small></article>`).join('')||'<p class="empty">Your first creation will begin this record.</p>'}</div>`;}

if(UI.modal==='automation'){name='Production rules';const a=s.automation;html=`<p>Keep a chosen item stocked automatically. Purchases respect your gold reserve and offline spending limit. Protected items stay safe.</p><label class="field">Recipe<select id="auto-recipe"><option value="">Choose a recipe</option>${visibleRecipes().map(r=>`<option value="${r.id}" ${a.recipeId===r.id?'selected':''}>${r.name}</option>`).join('')}</select></label><div class="policy-options">${[['enabled','Enable automatic production'],['autoBuy','Buy missing materials'],['autoSell','Sell surplus to town'],['allowRare','Allow rare-material crafting']].map(([id,label])=>`<label><input type="checkbox" data-automation="${id}" ${a[id]?'checked':''}> ${label}</label>`).join('')}</div><div class="row">${[['targetStock','Target stock'],['goldReserve','Gold reserve'],['spendCap','Offline purchase limit']].map(([id,label])=>`<label class="field">${label}<input type="number" min="0" max="1000000" data-auto-number="${id}" value="${a[id]}"></label>`).join('')}</div>`;}

if(UI.modal==='profile'){name=profile?'Your profile':'Protect this workshop';html=profile?`<p><strong>${esc(profile.username)}</strong> is keeping this workshop backed up.</p><p class="muted">Your current progress saves on this device and to your profile. You can sign in on another device at any time.</p>${btn('Play as guest on this device','logout-profile',{},false,'danger-button')}`:`<p>Keep playing as a guest for as long as you like. Create a simple profile before leaving this browser to preserve your current workshop.</p><label class="field">Profile name<input id="profile-name" maxlength="24" autocomplete="username" placeholder="forgeborn"></label><label class="field">Password<input id="profile-password" type="password" minlength="8" maxlength="200" autocomplete="new-password" placeholder="At least 8 characters"></label><div class="row">${btn('Create profile & save this workshop','signup-profile',{},false,'primary')}${btn('I already have a profile','login-profile')}</div><p class="muted">No email address required. Signing in restores the save already attached to that profile.</p>`;}

if(UI.modal==='settings'){name='Your workshop';html=`<section class="reset-run-section"><h3>${profile?'Profile: '+esc(profile.username):'Guest workshop'}</h3><p>${profile?'Your progress is backed up to this profile.':'This workshop currently lives only in this browser. Create a profile before changing browsers or devices.'}</p>${btn(profile?'Manage profile':'Create or sign in','modal',{modal:'profile'},false,'primary')}</section><div class="settings-grid">${btn('Export save','export')}${btn('Import save','import')}${btn('How to play','modal',{modal:'help'})}${btn('Full screen','fullscreen')}</div><section class="reset-run-section"><h3>Start over</h3><p>Reset your workshop and return to character creation. All progress, including Legacy, will be lost.</p>${btn('Reset run','modal',{modal:'reset'},UI.readonly,'danger-button')}</section><label class="field"><span><input type="checkbox" id="reduce-motion" ${UI.reduced?'checked':''}> Reduce motion</span></label><p>${UI.readonly?'Another open tab is running this workshop. Close it, then reload here to continue.':profile?'Progress saves automatically to this device and your profile.':'Progress saves automatically on this device.'}</p><p class="muted">The Foundry · v1.5.0 · exports remain available as an extra backup.</p>`;}

if(UI.modal==='reset'){name='Reset this run?';html=`<div class="reset-warning"><strong>Warning: all progress will be permanently lost.</strong><p>This erases your smith, gold, materials, items, upgrades, heroes, quests, Legacy sparks, talents and collection. Your local save and automatic backup will be replaced with a fresh game.</p><p>No retirement rewards are granted. Export your save first if you might want to return to this workshop.</p></div><div class="reset-export">${btn('Export save before resetting','export')}</div><div class="row reset-actions">${btn('Cancel - keep my progress','close',{},false,'primary')}${btn('Yes, reset all progress','reset-run',{},UI.readonly,'danger-button')}</div>`;}

if(UI.modal==='help'){name='From a quiet forge to a lasting legacy';html=`<ol class="help-steps"><li><strong>Shape your smith.</strong> Your profession and uncapped attributes affect quality, speed, customers and learning.</li><li><strong>Mine the mountain.</strong> Click seams, assign workers, and earn Prospecting. Buy wood and leather in Mine or Forge; trade other materials in Open workings.</li><li><strong>Choose a craft.</strong> Bronze starts modestly. Repeat a class to build proficiency, or make armour and accessories to broaden a hero’s equipment.</li><li><strong>Fill the displays.</strong> Finished work occupies an open display automatically. Customers buy only useful, affordable improvements.</li><li><strong>Watch the consequences.</strong> Heroes quest automatically. Defeated heroes rest, return for upgrades, and retry. Victories bring reputation and discoveries.</li><li><strong>Invest in each room.</strong> Mine uses Prospecting, forge uses gold, shop uses Influence, and adventurers use Merits earned from completed quests.</li><li><strong>Leave a legacy.</strong> After defeating the tier 5 boss, retire to unlock permanent talents and begin another generation.</li></ol><p class="muted">The early workshop earns little. A stronger material, a familiar class and a balanced loadout often matter more than producing the most expensive piece.</p>`;}

const content=overlay(name,html,wide);if(content===modalStamp)return;const old=$('.modal-body')?.scrollTop||0,focus=document.activeElement?.id;const t=document.createElement('template');t.innerHTML=content;syncChildren($('#modal-root'),t.content);$('.modal-body').scrollTop=old;modalStamp=content;if(focus&&document.getElementById(focus))document.getElementById(focus).focus({preventScroll:true});}

function close(){UI.modal=null;$('#modal-root').innerHTML='';modalStamp='';modalFocus?.isConnected&&modalFocus.focus();}

function resetRun(){
 if(UI.modal!=='reset')return;
 lease();if(UI.readonly){toast('Another tab is running this workshop. Close it and reload here.');return;}
 const fresh=new EIWorldEngine(D),now=Date.now();fresh.markSaved(now);const raw=fresh.exportSave();
 if(!put(SAVE,raw)){toast('Reset cancelled: your fresh save could not be stored. Your current game is still running.');return;}
 put(BACKUP,raw);game=fresh;lastTime=now;lastSave=now;
 Object.assign(UI,{room:'smith',selectedHero:null,followHero:null,type:'swords',group:'weapons',heroes:[{name:'Mara',archetypeId:'vanguard'},{name:'Renn',archetypeId:'duelist'},{name:'Wren',archetypeId:'ranger'}],tier:'all',creation:{strength:7,precision:7,charisma:7,knowledge:7},profession:'weaponsmith',name:'Ember & Iron'});
 close();$('#app').innerHTML='';render();toast('Run reset. Create a new smith to begin again.');
}

function act(action,payload){if(UI.readonly){toast('Another tab is running this workshop. Close it and reload here.');return;}const r=game.command(action,payload);toast(r.message);if(r.ok){if(UI.modal==='item'&&['sell','salvage','gift'].includes(action)&&payload.itemId===UI.id)close();save(true);render();renderModal();}return r;}

document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;switch(a){case'signup-profile':await profileAction('signup');break;case'login-profile':await profileAction('login');break;case'logout-profile':await logoutProfile();break;case'group-filter':UI.group=el.dataset.group;render();break;case'recruit':UI.recruitName='';UI.recruitClass='vanguard';open('recruit',id);break;case'confirm-recruit':{const result=act('recruitHero',{id,name:UI.recruitName,archetypeId:UI.recruitClass});if(result?.ok){close();render();}break;}case'boss-party':UI.bossHeroes=game.state.world.bossTarget===id?[...game.state.world.bossParty]:[];open('boss',id);break;case'release-boss':act('releaseBoss',{});break;case'gather-launch-boss':{const result=act('gatherAndLaunchBoss',{questId:id,heroIds:UI.bossHeroes});if(result?.ok){UI.selectedHero=UI.bossHeroes[0];UI.followHero=null;UI.room='adventurers';close();render();}break;}case'select-hero':UI.selectedHero=id;UI.followHero=null;UI.room='adventurers';close();render();break;case'follow-hero':UI.followHero=id;UI.selectedHero=id;close();render();break;case'stop-follow':UI.followHero=null;render();break;case'room':if(el.dataset.room==='legacy'&&!EIRoomModel.legacyUnlocked(game))break;UI.followHero=null;UI.room=el.dataset.room;close();render();break;case'modal':open(el.dataset.modal);break;case'close':close();break;case'creation-stat':UI.name=$('#shop-name').value;UI.creation[el.dataset.stat]+=Number(el.dataset.delta);$('#app').innerHTML=creation();break;case'create':UI.name=$('#shop-name').value;act('create',{name:UI.name,stats:UI.creation,profession:UI.profession,heroes:UI.heroes});break;case'allocate':act('allocate',{stat:el.dataset.stat});break;case'filter':UI.type=el.dataset.type;render();break;case'craft':act('craft',{recipeId:el.dataset.recipe,quantity:Number(el.dataset.quantity)});break;case'mine':act('mine',{materialId:el.dataset.material});break;case'hire':act('hireMiner');break;case'tree':act('tree',{id});break;case'buy':act('buyMaterial',{materialId:el.dataset.material,quantity:Number(el.dataset.quantity)});break;case'sell-material':act('sellMaterial',{materialId:el.dataset.material,quantity:Number(el.dataset.quantity)});break;case'technique':act('technique',{jobId:id});break;case'cancel':act('cancel',{jobId:id});break;case'item':open('item',id);break;case'hero':open('hero',id);break;case'watch':open('watch',id);break;case'display':case'protect':case'salvage':act(a,{itemId:id});break;case'town-sell':act('sell',{itemId:id});break;case'enchant':act('enchant',{itemId:id,enchantmentId:el.dataset.enchantment});break;case'staff-toggle':act('toggleStaff',{staffId:id});break;case'staff-hire':act('hireStaff',{staffId:id});break;case'decorate':act('decorate',{decorId:id});break;case'claim':act('claim',{bundleId:id});break;case'scrap-threshold':{const field=$('#scrap-quality');if(field.value===''||!field.checkValidity()){field.reportValidity();toast('Choose a whole quality from 0 to 200.');break;}const result=act('policy',{key:'scrapQuality',value:Number(field.value)});if(result?.ok)UI.scrapQuality=null;break;}case'party':act('policy',{key:'party',value:el.dataset.value});break;case'talent':act('talent',{talentId:id});break;case'respec':act('respec');break;case'retire':{const r=act('retire',{confirmed:true,heirloomItemId:$('#heirloom').value||null});if(r?.ok){UI.room='smith';close();$('#app').innerHTML=creation();}break;}case'reset-run':resetRun();break;case'export':{const blob=new Blob([game.exportSave()],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Ember-and-Iron-save.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Save exported.');break;}case'import':$('#import-file').click();break;case'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch(e){toast('Use your browser’s full screen option.');}break;}});

document.addEventListener('input',e=>{const el=e.target;if(el.id==='scrap-quality')UI.scrapQuality=el.value;if(el.id==='shop-name')UI.name=el.value;if(el.dataset.companyName!==undefined)UI.heroes[Number(el.dataset.companyName)].name=el.value;if(el.id==='recruit-name'){UI.recruitName=el.value;renderModal();}});

document.addEventListener('change',e=>{const el=e.target;if(el.dataset.companyClass!==undefined){UI.heroes[Number(el.dataset.companyClass)].archetypeId=el.value;UI.name=$('#shop-name').value;$('#app').innerHTML=creation();}if(el.id==='recruit-class'){UI.recruitClass=el.value;renderModal();}if(el.dataset.bossHero){UI.bossHeroes=UI.bossHeroes||[];if(el.checked&&!UI.bossHeroes.includes(el.dataset.bossHero)){if(UI.bossHeroes.length>=3){el.checked=false;toast('Choose at most three heroes.');return;}UI.bossHeroes.push(el.dataset.bossHero);}else UI.bossHeroes=UI.bossHeroes.filter(id=>id!==el.dataset.bossHero);renderModal();}if(el.dataset.automation)act('automation',{[el.dataset.automation]:el.checked});if(el.dataset.autoNumber)act('automation',{[el.dataset.autoNumber]:Number(el.value)});if(el.id==='auto-recipe')act('automation',{recipeId:el.value||null});if(el.id==='profession'){UI.name=$('#shop-name').value;UI.profession=el.value;$('#app').innerHTML=creation();}if(el.id==='tier-filter'){UI.tier=el.value;render();}if(el.dataset.worker)act('assignWorker',{id:el.dataset.worker,materialId:el.value});if(el.id==='auto-scrap')act('policy',{key:'autoScrap',value:el.checked});if(el.id==='reduce-motion'){UI.reduced=el.checked;document.body.classList.toggle('reduce-motion',UI.reduced);EIWorldScenes.motion(UI.reduced);}});

$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(UI.readonly){toast('Close the other workshop tab before importing.');return;}try{if(file.size>12000000)throw Error('Save is too large.');const raw=await file.text(),c=EIWorldEngine.validateSave(raw,D);if(!c.ok)throw Error(c.message);const r=game.importSave(raw);if(!r.ok)throw Error(r.message);game.advanceOffline(Date.now());lastTime=Date.now();save(true);close();$('#app').innerHTML='';render();toast('Your workshop has been restored.');}catch(err){toast('Import failed: '+err.message);}e.target.value='';});

document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&UI.modal){const els=[...$('.modal').querySelectorAll('button:not(:disabled),select,input,a[href],[tabindex="0"]')],first=els[0],last=els[els.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){last?.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault();}}});

window.addEventListener('storage',e=>{if(e.key===LEASE){try{const l=JSON.parse(e.newValue);if(l&&l.owner!==owner)UI.readonly=true;}catch(e){}}});

window.addEventListener('pagehide',()=>{save(true);try{if(JSON.parse(get(LEASE)||'null')?.owner===owner)localStorage.removeItem(LEASE);}catch(e){}});

render();setInterval(()=>{const now=Date.now();if(!UI.readonly){game.tick(Math.min(now-lastTime,8*3600000),{offline:document.hidden||now-lastTime>10000});save();}lastTime=now;if(game.state.started){render();if(UI.modal&&!['settings','retire','reset','help'].includes(UI.modal))renderModal();}},1000);setInterval(()=>{if(!UI.readonly)lease();},3000);

})();
